-- OpenBooks canonical PostgreSQL baseline.
--
-- This file defines the complete schema for a fresh installation: tables,
-- constraints, indexes, functions, triggers, row-level security policies,
-- governed query views, and grants. Deployment bootstrap applies it exactly
-- once and records its digest in _applied_migrations.

SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
--
-- Name: openbooks_query; Type: SCHEMA; Schema: -; Owner: -
--

CREATE SCHEMA openbooks_query;


-- Trigram search is an optional acceleration. PostgreSQL providers that do
-- not allow application roles to install extensions still receive the full
-- canonical schema and use the application's substring-search fallback.
DO $extension$
BEGIN
  CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public;
EXCEPTION
  WHEN insufficient_privilege OR undefined_file THEN
    RAISE NOTICE 'pg_trgm is unavailable; trigram indexes will be skipped';
END
$extension$;


--
-- Name: app_check_open(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_check_open() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_line numeric(19,4);
  v_applied numeric(19,4);
  v_transaction numeric(19,4);
begin
  if new.unapplied_at is not null then return new; end if;
  -- target side: total applied to the open item <= |line amount|
  select abs(amount) into v_line from journal_lines where id = new.to_line_id;
  select coalesce(sum(amount), 0) into v_applied
    from applications
   where to_line_id = new.to_line_id and unapplied_at is null and id <> new.id;
  if v_applied + new.amount > v_line then
    raise exception 'application exceeds open amount on target line % (% applied of %)',
      new.to_line_id, v_applied + new.amount, v_line;
  end if;

  select abs(txn_amount) into v_line from journal_lines where id = new.to_line_id;
  select coalesce(sum(target_transaction_amount), 0) into v_transaction from applications
   where to_line_id = new.to_line_id and unapplied_at is null and id <> new.id;
  if v_transaction + new.target_transaction_amount > v_line then
    raise exception 'application exceeds transaction amount on target line %', new.to_line_id using errcode = '23514';
  end if;

  -- source side uses its independently recorded carrying amount.
  select abs(amount) into v_line from journal_lines where id = new.from_line_id;
  select coalesce(sum(source_amount), 0) into v_applied
    from applications
   where from_line_id = new.from_line_id and unapplied_at is null and id <> new.id;
  if v_applied + new.source_amount > v_line then
    raise exception 'application exceeds available amount on source line %', new.from_line_id using errcode = '23514';
  end if;
  select abs(txn_amount) into v_line from journal_lines where id = new.from_line_id;
  select coalesce(sum(source_transaction_amount), 0) into v_transaction from applications
   where from_line_id = new.from_line_id and unapplied_at is null and id <> new.id;
  if v_transaction + new.source_transaction_amount > v_line then
    raise exception 'application exceeds transaction amount on source line %', new.from_line_id using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: app_validate_endpoints(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_validate_endpoints() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_from journal_lines%rowtype;
  v_to journal_lines%rowtype;
  v_fx fx_rates%rowtype;
  v_status_count integer;
begin
  -- Bulk migration / sandbox-clone copies pre-validated application rows through
  -- ob_rebase before their journal lines exist in the target, so this row-by-row
  -- cross-reference check can't hold mid-copy. 'set local openbooks.migration = on'
  -- (transaction-scoped, direct-DB only) relaxes it; every normal write still
  -- validates in full.
  if coalesce(current_setting('openbooks.migration', true), 'off') = 'on' then
    return new;
  end if;
  -- Deterministic row locks serialize competing applications to either line.
  perform id from journal_lines
   where id in (new.from_line_id, new.to_line_id)
   order by id for update;
  select * into v_from from journal_lines where id = new.from_line_id;
  select * into v_to from journal_lines where id = new.to_line_id;
  if v_from.id is null or v_to.id is null or v_from.id = v_to.id then
    raise exception 'application endpoints must be two distinct journal lines' using errcode = '23514';
  end if;
  if v_from.org_id <> new.org_id or v_to.org_id <> new.org_id
     or v_from.org_id <> v_to.org_id then
    raise exception 'application endpoints must belong to the application tenant' using errcode = '23514';
  end if;
  if new.unapplied_at is not null then return new; end if;
  if not v_from.is_open_item or not v_to.is_open_item then
    raise exception 'applications require open-item journal lines' using errcode = '23514';
  end if;
  if v_from.account_id <> v_to.account_id
     or v_from.party_id is distinct from v_to.party_id
     or v_from.subsidiary_id <> v_to.subsidiary_id then
    raise exception 'application endpoints must share account, party, and subsidiary' using errcode = '23514';
  end if;
  if sign(v_from.amount) = sign(v_to.amount) then
    raise exception 'application endpoints must have opposite debit/credit signs' using errcode = '23514';
  end if;
  if v_from.currency <> new.source_transaction_currency
     or v_to.currency <> new.target_transaction_currency then
    raise exception 'application source and target currencies must match their journal lines' using errcode = '23514';
  end if;
  if abs(new.target_transaction_amount - round(new.source_transaction_amount * new.settlement_rate, 4)) > 0.0001 then
    raise exception 'application settlement rate does not cross-foot source and target transaction amounts' using errcode = '23514';
  end if;
  if new.source_transaction_currency = new.target_transaction_currency then
    if new.source_transaction_amount <> new.target_transaction_amount
       or new.settlement_rate <> 1
       or new.settlement_rate_source <> 'same_currency' then
      raise exception 'same-currency applications require equal transaction amounts and a rate of one' using errcode = '23514';
    end if;
  elsif new.settlement_rate_source = 'same_currency' then
    raise exception 'cross-currency applications require explicit settlement-rate evidence' using errcode = '23514';
  end if;
  if new.settlement_rate_source = 'provider' and new.settlement_fx_rate_id is null then
    raise exception 'provider settlement evidence requires an FX rate observation' using errcode = '23514';
  end if;
  if new.settlement_fx_rate_id is not null then
    select * into v_fx from fx_rates where id = new.settlement_fx_rate_id;
    if v_fx.id is null
       or v_fx.org_id <> new.org_id
       or v_fx.from_currency <> new.source_transaction_currency
       or v_fx.to_currency <> new.target_transaction_currency
       or v_fx.rate <> new.settlement_rate
       or v_fx.as_of > new.applied_on then
      raise exception 'settlement FX observation does not match the application evidence' using errcode = '23514';
    end if;
  end if;
  select count(*) into v_status_count from journal_entries
   where id in (v_from.entry_id, v_to.entry_id) and status = 'posted';
  if v_status_count <> 2 then
    raise exception 'applications may only connect posted journal entries' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: application_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.application_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if openbooks_sandbox_wipe_allowed(old.org_id) then return old; end if;
    raise exception 'application evidence is immutable; unapply it instead';
  end if;
  if new.org_id is distinct from old.org_id
     or new.from_line_id is distinct from old.from_line_id
     or new.to_line_id is distinct from old.to_line_id
     or new.amount is distinct from old.amount
     or new.source_amount is distinct from old.source_amount
     or new.source_transaction_amount is distinct from old.source_transaction_amount
     or new.source_transaction_currency is distinct from old.source_transaction_currency
     or new.target_transaction_amount is distinct from old.target_transaction_amount
     or new.target_transaction_currency is distinct from old.target_transaction_currency
     or new.settlement_rate is distinct from old.settlement_rate
     or new.settlement_rate_source is distinct from old.settlement_rate_source
     or new.settlement_rate_reference is distinct from old.settlement_rate_reference
     or new.settlement_fx_rate_id is distinct from old.settlement_fx_rate_id
     or new.applied_on is distinct from old.applied_on
     or new.fx_gain_loss_entry_id is distinct from old.fx_gain_loss_entry_id
     or old.unapplied_at is not null
     or new.unapplied_at is null then
    raise exception 'application evidence is immutable; only a one-time unapply is allowed';
  end if;
  return new;
end $$;


--
-- Name: assert_active_user_has_role(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_active_user_has_role(checked_user_id uuid, checked_org_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
      FROM users u
     WHERE u.id = checked_user_id
       AND u.org_id = checked_org_id
       AND u.is_active
       AND NOT EXISTS (
         SELECT 1
           FROM role_assignments assignment
          WHERE assignment.user_id = u.id
            AND assignment.org_id = u.org_id
       )
  ) THEN
    RAISE EXCEPTION 'active user % must have at least one explicit role assignment', checked_user_id;
  END IF;
END;
$$;


--
-- Name: asset_event_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asset_event_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  source record;
BEGIN
  IF tg_op IN ('UPDATE', 'DELETE') THEN
    IF openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN coalesce(new, old);
    END IF;
    RAISE EXCEPTION
      'asset lifecycle evidence is append-only; post a linked reversal event';
  END IF;

  IF new.kind = 'reversed' THEN
    SELECT id, org_id, asset_id, kind, journal_entry_id
      INTO source
      FROM asset_events
     WHERE id = new.reverses_event_id
     FOR KEY SHARE;
    IF source.id IS NULL
       OR source.org_id <> new.org_id
       OR source.asset_id <> new.asset_id
       OR source.kind NOT IN ('revalued', 'impaired', 'disposed', 'written_off')
       OR source.journal_entry_id IS NULL
    THEN
      RAISE EXCEPTION
        'an asset reversal must reference a reversible event for the same tenant and asset';
    END IF;
  END IF;
  RETURN new;
END
$$;


--
-- Name: audit_log_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_log_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'audit_log is append-only';
end $$;


--
-- Name: billing_request_field_ticket_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_request_field_ticket_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE request_project_id uuid; request_basis text; request_status text; BEGIN IF tg_op = 'DELETE' AND openbooks_sandbox_wipe_allowed(old.org_id) THEN RETURN old; END IF; IF tg_op IN ('UPDATE', 'DELETE') THEN RAISE EXCEPTION 'billing request Field Ticket selections are immutable; cancel the request and create a new one'; END IF; SELECT br.project_id, br.basis, br.status INTO request_project_id, request_basis, request_status FROM billing_requests br WHERE br.id = new.billing_request_id AND br.org_id = new.org_id; IF request_project_id IS NULL OR request_basis <> 'field_ticket' OR request_status <> 'open' THEN RAISE EXCEPTION 'Field Ticket selections require an open field-ticket billing request in the same organization'; END IF; IF NOT EXISTS (SELECT 1 FROM documents ticket WHERE ticket.id = new.field_ticket_id AND ticket.org_id = new.org_id AND ticket.project_id = request_project_id AND ticket.kind = 'field_ticket' AND ticket.status = 'approved') THEN RAISE EXCEPTION 'selected Field Ticket must be approved and belong to the billing request project'; END IF; IF new.selected_by IS NOT NULL AND NOT EXISTS (SELECT 1 FROM users actor WHERE actor.id = new.selected_by AND actor.org_id = new.org_id) THEN RAISE EXCEPTION 'Field Ticket selection actor must belong to the same organization'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('billing-field-ticket:' || new.org_id::text || ':' || new.field_ticket_id::text, 0)); IF EXISTS (SELECT 1 FROM billing_request_field_tickets existing JOIN billing_requests existing_request ON existing_request.id = existing.billing_request_id AND existing_request.org_id = existing.org_id WHERE existing.org_id = new.org_id AND existing.field_ticket_id = new.field_ticket_id AND existing_request.status <> 'cancelled') THEN RAISE EXCEPTION 'Field Ticket is already selected by another active or completed billing request'; END IF; RETURN new; END; $$;


--
-- Name: billing_request_field_ticket_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_request_field_ticket_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  selection_count bigint;
BEGIN
  SELECT count(*)
    INTO selection_count
    FROM billing_request_field_tickets selected
   WHERE selected.org_id = new.org_id
     AND selected.billing_request_id = new.id;

  IF new.basis = 'field_ticket' AND selection_count = 0 THEN
    RAISE EXCEPTION
      'a Field Ticket billing request requires at least one relational ticket selection';
  END IF;

  IF new.basis <> 'field_ticket' AND selection_count <> 0 THEN
    RAISE EXCEPTION
      'Field Ticket selections may only belong to a field-ticket billing request';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM billing_request_field_tickets selected
      JOIN documents ticket
        ON ticket.id = selected.field_ticket_id
       AND ticket.org_id = selected.org_id
     WHERE selected.org_id = new.org_id
       AND selected.billing_request_id = new.id
       AND (
         ticket.kind <> 'field_ticket'
         OR ticket.project_id IS DISTINCT FROM new.project_id
       )
  ) THEN
    RAISE EXCEPTION
      'Field Ticket billing selections must remain in the request organization and project';
  END IF;

  RETURN new;
END;
$$;


--
-- Name: change_order_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_order_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.target_sov_line_id is not null and not exists (
    select 1
      from sov_lines sl
     where sl.id = new.target_sov_line_id
       and sl.org_id = new.org_id
       and sl.project_id = new.project_id
  ) then
    raise exception 'change-order target must belong to the same organization and project';
  end if;
  return new;
end $$;


--
-- Name: close_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception '% is append-only', tg_table_name;
end $$;


--
-- Name: depreciation_evidence_attachment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_evidence_attachment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if current_setting('openbooks.sandbox_wipe', true) = 'on' then return coalesce(new, old); end if;
  if old.target_table = 'fixed_assets' and exists (
    select 1
      from depreciation_inputs i
      join depreciation_schedules s on s.id = i.schedule_id
     where i.org_id = old.org_id and i.evidence_file_id = old.file_id and s.asset_id = old.target_id
  ) then
    raise exception 'file attachment is retained by depreciation evidence';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: depreciation_input_file_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_input_file_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  owning_asset uuid;
begin
  select s.asset_id into owning_asset
    from depreciation_schedules s
   where s.id = new.schedule_id and s.org_id = new.org_id;
  if owning_asset is null then
    raise exception 'depreciation input schedule must belong to the tenant';
  end if;
  if not exists (select 1 from files f where f.id = new.evidence_file_id and f.org_id = new.org_id and not f.is_inactive) then
    raise exception 'depreciation evidence file must be active and belong to the tenant';
  end if;
  if not exists (
    select 1 from file_attachments fa
     where fa.org_id = new.org_id and fa.file_id = new.evidence_file_id
       and fa.target_table = 'fixed_assets' and fa.target_id = owning_asset
  ) then
    raise exception 'depreciation evidence file must be attached to the owning fixed asset';
  end if;
  return new;
end $$;


--
-- Name: depreciation_method_definition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.depreciation_method_definition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.org_id is distinct from old.org_id
      or new.formula is distinct from old.formula
      or new.end_of_life is distinct from old.end_of_life
      or new.is_active is distinct from old.is_active) and exists (
    select 1 from depreciation_schedules s where s.depreciation_method_id = old.id
  ) then
    raise exception 'a depreciation formula used by a schedule is immutable; create a new method version';
  end if;
  return new;
end $$;


--
-- Name: document_correction_lineage_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_correction_lineage_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  replacement record;
  source record;
BEGIN
  IF tg_op <> 'INSERT' THEN
    IF old.link_type = 'reverses'
       AND NOT openbooks_sandbox_wipe_allowed(old.org_id)
    THEN
      RAISE EXCEPTION
        'document correction lineage is immutable; retain the source and replacement';
    END IF;
    RETURN coalesce(new, old);
  END IF;

  IF new.link_type <> 'reverses' THEN
    RETURN new;
  END IF;

  SELECT id, org_id, kind, status, posted_entry_id
    INTO replacement
    FROM documents
   WHERE id = new.from_document_id
   FOR KEY SHARE;
  SELECT id, org_id, kind, status, posted_entry_id
    INTO source
    FROM documents
   WHERE id = new.to_document_id
   FOR KEY SHARE;

  IF replacement.id IS NULL OR source.id IS NULL
     OR replacement.org_id <> new.org_id
     OR source.org_id <> new.org_id
  THEN
    RAISE EXCEPTION
      'a correction source and replacement must belong to the same tenant';
  END IF;
  IF replacement.id = source.id THEN
    RAISE EXCEPTION 'a document cannot correct itself';
  END IF;
  IF replacement.kind <> source.kind THEN
    RAISE EXCEPTION
      'a correction must retain the source document kind';
  END IF;
  IF source.status NOT IN ('posted', 'voided') THEN
    RAISE EXCEPTION
      'only a posted or already-voided document can be the source of a correction';
  END IF;
  IF replacement.status <> 'draft'
     OR replacement.posted_entry_id IS NOT NULL
  THEN
    RAISE EXCEPTION
      'correction lineage must be established while the replacement is an unposted draft';
  END IF;
  RETURN new;
END
$$;


--
-- Name: document_line_tax_component_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.document_line_tax_component_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_status text;
declare v_org uuid;
begin
  v_org := case when tg_op = 'DELETE' then old.org_id else new.org_id end;
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(v_org) then return old; end if;
  select d.status into v_status
    from documents d join document_lines dl on dl.document_id = d.id
   where dl.id = case when tg_op = 'DELETE' then old.document_line_id else new.document_line_id end;
  if v_status <> 'draft'
     and coalesce(current_setting('openbooks.amend', true), 'off') <> 'on' then
    raise exception 'posted tax calculation evidence is immutable';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: dunning_log_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dunning_log_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if current_setting('app.bypass_rls', true) = 'on' then
    return coalesce(new, old);
  end if;
  raise exception 'dunning_log is append-only';
end;
$$;


--
-- Name: effective_date_ranges_overlap(date, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.effective_date_ranges_overlap(a_from date, a_to date, b_from date, b_to date) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select daterange(a_from, coalesce(a_to, 'infinity'::date), '[]')
      && daterange(b_from, coalesce(b_to, 'infinity'::date), '[]')
$$;


--
-- Name: enforce_deleted_role_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_deleted_role_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM assert_active_user_has_role(OLD.user_id, OLD.org_id);
  RETURN NULL;
END;
$$;


--
-- Name: enforce_user_active_role_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_user_active_role_assignment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM assert_active_user_has_role(NEW.id, NEW.org_id);
  RETURN NULL;
END;
$$;


--
-- Name: entitlement_ledger_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.entitlement_ledger_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'UPDATE' then
    raise exception
      'entitlement_ledger is append-only; correct a balance with an adjustment movement';
  end if;
  if openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  if old.pay_run_document_id is not null and exists (
    select 1 from pay_runs r
     where r.document_id = old.pay_run_document_id
       and r.run_status <> 'committed'
  ) then
    return old;
  end if;
  if old.kind = 'opening' and old.pay_run_document_id is null then
    if exists (
      select 1 from pay_stubs s
        join pay_runs r on r.document_id = s.pay_run_document_id and r.org_id = s.org_id
       where s.org_id = old.org_id
         and s.employee_party_id = old.employee_party_id
         and r.run_status = 'committed'
         and s.pay_date >= old.movement_date
    ) then
      raise exception
        'entitlement_ledger opening carry-in has already been consumed by a committed pay run; void that run before changing it';
    end if;
    return old;
  end if;
  raise exception
    'entitlement_ledger movements cannot be deleted once their pay run is committed';
end $$;


--
-- Name: fair_value_prices_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fair_value_prices_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not new.is_active then return new; end if;
  if exists (
    select 1
      from fair_value_prices f
     where f.id <> new.id
       and f.org_id = new.org_id
       and f.is_active
       and f.item_id = new.item_id
       and f.currency = new.currency
       and effective_date_ranges_overlap(coalesce(f.effective_from, '-infinity'::date), f.effective_to, coalesce(new.effective_from, '-infinity'::date), new.effective_to)
  ) then
    raise exception 'active fair-value prices overlap for the same item and currency' using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: field_ticket_evidence_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_evidence_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (
    select 1 from field_tickets ft
     where ft.document_id = new.field_ticket_id and ft.org_id = new.org_id
  ) then
    raise exception 'field ticket evidence must belong to the same organization'
      using errcode = '23514';
  end if;
  if tg_table_name = 'field_ticket_signatures' and not exists (
    select 1 from files f
     where f.id = new.signature_file_id and f.org_id = new.org_id
  ) then
    raise exception 'field ticket signature file must belong to the same organization'
      using errcode = '23514';
  end if;
  if tg_table_name = 'field_ticket_signature_requests'
     and new.email_log_id is not null and not exists (
       select 1 from email_log e
        where e.id = new.email_log_id and e.org_id = new.org_id
     )
  then
    raise exception 'field ticket signature email evidence must belong to the same organization'
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: field_ticket_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (
    select 1 from documents d
     where d.id = new.document_id and d.org_id = new.org_id
       and d.kind = 'field_ticket'
  ) then
    raise exception 'field ticket header must extend a field_ticket document in the same organization'
      using errcode = '23514';
  end if;
  if new.foreman_party_id is not null and not exists (
    select 1 from parties p where p.id = new.foreman_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket foreman must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.charge_document_id is not null and not exists (
    select 1 from documents d where d.id = new.charge_document_id and d.org_id = new.org_id
  ) then
    raise exception 'field ticket charge document must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then
    raise exception 'field ticket submitter must belong to the same organization'
      using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: field_ticket_labor_line_classification_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_line_classification_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  configured_classification text;
BEGIN
  IF new.time_type_id IS NOT NULL THEN
    SELECT classification
      INTO configured_classification
      FROM time_types
     WHERE id = new.time_type_id
       AND org_id = new.org_id;
  END IF;
  IF new.time_classification IS NULL THEN
    new.time_classification := coalesce(
      configured_classification,
      CASE
        WHEN lower(new.time_type_name) LIKE '%double%' THEN 'double_time'
        WHEN lower(new.time_type_name) LIKE '%over%' THEN 'overtime'
        ELSE 'regular'
      END
    );
  ELSIF configured_classification IS NOT NULL
        AND new.time_classification IS DISTINCT FROM configured_classification
  THEN
    RAISE EXCEPTION
      'field ticket labor classification must match its time type at capture'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_labor_line_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_line_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'field ticket labor snapshot lines are append-only evidence';
END
$$;


--
-- Name: field_ticket_labor_line_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_line_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  linked_time time_entries%ROWTYPE;
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM field_ticket_labor_snapshots snapshot
     WHERE snapshot.id = new.snapshot_id
       AND snapshot.org_id = new.org_id
       AND snapshot.field_ticket_id = new.field_ticket_id
       AND snapshot.superseded_at IS NULL
  ) THEN
    RAISE EXCEPTION
      'field ticket labor line must belong to the current snapshot and ticket in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM parties p
     WHERE p.id = new.employee_party_id AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor employee must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.item_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM items i WHERE i.id = new.item_id AND i.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor item must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.time_type_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM time_types tt
     WHERE tt.id = new.time_type_id AND tt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor time type must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.project_task_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_tasks pt
      JOIN documents d
        ON d.id = new.field_ticket_id
       AND d.org_id = pt.org_id
       AND d.project_id = pt.project_id
     WHERE pt.id = new.project_task_id
       AND pt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor task must belong to the ticket project'
      USING ERRCODE = '23514';
  END IF;
  IF new.created_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u WHERE u.id = new.created_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor line actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;

  -- An optional link means exact atomic provenance, not a fuzzy association.
  IF new.time_entry_id IS NOT NULL THEN
    SELECT * INTO linked_time
      FROM time_entries te
     WHERE te.id = new.time_entry_id
       AND te.org_id = new.org_id;
    IF NOT FOUND
       OR linked_time.field_ticket_id IS DISTINCT FROM new.field_ticket_id
       OR linked_time.employee_party_id IS DISTINCT FROM new.employee_party_id
       OR linked_time.item_id IS DISTINCT FROM new.item_id
       OR linked_time.time_type_id IS DISTINCT FROM new.time_type_id
       OR linked_time.project_task_id IS DISTINCT FROM new.project_task_id
       OR linked_time.worked_on IS DISTINCT FROM new.worked_on
       OR linked_time.hours IS DISTINCT FROM new.hours
    THEN
      RAISE EXCEPTION
        'field ticket labor time-entry provenance must be an exact line on the same ticket'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_labor_snapshot_integrity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_snapshot_integrity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
      FROM field_tickets ft
      JOIN documents d
        ON d.id = ft.document_id
       AND d.org_id = ft.org_id
       AND d.kind = 'field_ticket'
     WHERE ft.document_id = new.field_ticket_id
       AND ft.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'field ticket labor snapshot must belong to a Field Ticket in the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.captured_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.captured_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users u
     WHERE u.id = new.superseded_by AND u.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION 'field ticket labor snapshot superseding actor must belong to the same organization'
      USING ERRCODE = '23514';
  END IF;
  IF new.superseded_at IS NOT NULL AND new.superseded_at < new.captured_at THEN
    RAISE EXCEPTION 'field ticket labor snapshot cannot be superseded before capture'
      USING ERRCODE = '23514';
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_labor_snapshot_retention_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_labor_snapshot_retention_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'field ticket labor snapshots are retained evidence';
  END IF;
  IF row(new.org_id, new.field_ticket_id, new.revision, new.evidence_basis,
         new.reason, new.source_system, new.source_payload_hash, new.currency,
         new.captured_by, new.captured_at)
     IS DISTINCT FROM
     row(old.org_id, old.field_ticket_id, old.revision, old.evidence_basis,
         old.reason, old.source_system, old.source_payload_hash, old.currency,
         old.captured_by, old.captured_at)
  THEN
    RAISE EXCEPTION 'field ticket labor snapshot evidence is immutable';
  END IF;
  IF old.superseded_at IS NOT NULL
     AND row(new.superseded_at, new.superseded_by)
         IS DISTINCT FROM row(old.superseded_at, old.superseded_by)
  THEN
    RAISE EXCEPTION 'field ticket labor snapshot supersession is immutable once recorded';
  END IF;
  IF old.superseded_at IS NULL
     AND (new.superseded_at IS NULL OR new.superseded_by IS NULL)
  THEN
    RAISE EXCEPTION 'field ticket labor snapshot may only change through a complete supersession';
  END IF;
  RETURN new;
END
$$;


--
-- Name: field_ticket_policy_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_policy_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.customer_party_id is not null and not exists (
    select 1 from parties p
     where p.id = new.customer_party_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket customer policy must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.project_id is not null and not exists (
    select 1 from projects p
     where p.id = new.project_id and p.org_id = new.org_id
  ) then
    raise exception 'field ticket project policy must belong to the same organization'
      using errcode = '23514';
  end if;
  if new.is_active and exists (
    select 1 from field_ticket_policies existing
     where existing.org_id = new.org_id
       and existing.id <> new.id
       and existing.is_active
       and existing.scope = new.scope
       and existing.customer_party_id is not distinct from new.customer_party_id
       and existing.project_id is not distinct from new.project_id
       and daterange(existing.effective_from, existing.effective_to, '[]')
           && daterange(new.effective_from, new.effective_to, '[]')
  ) then
    raise exception 'effective Field Ticket policies cannot overlap for the same scope'
      using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: field_ticket_signature_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_signature_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  raise exception 'field ticket signatures are append-only evidence';
end $$;


--
-- Name: field_ticket_signature_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.field_ticket_signature_request_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'field ticket signature requests are retained evidence';
  end if;
  if row(new.org_id, new.field_ticket_id, new.recipient, new.message,
         new.expires_at, new.token_digest, new.email_log_id,
         new.created_by, new.created_at)
     is distinct from
     row(old.org_id, old.field_ticket_id, old.recipient, old.message,
         old.expires_at, old.token_digest, old.email_log_id,
         old.created_by, old.created_at)
  then
    raise exception 'field ticket signature request evidence is immutable';
  end if;
  if old.responded_at is not null and new.responded_at is distinct from old.responded_at then
    raise exception 'field ticket signature response timestamp is immutable once set';
  end if;
  if old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then
    raise exception 'field ticket signature revocation timestamp is immutable once set';
  end if;
  if old.sent_at is not null and new.sent_at is distinct from old.sent_at then
    raise exception 'field ticket signature delivery timestamp is immutable once set';
  end if;
  return new;
end $$;


--
-- Name: fixed_asset_configuration_org_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fixed_asset_configuration_org_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  method_id uuid;
  account_ids uuid[];
begin
  if tg_table_name = 'asset_categories' then
    method_id := new.default_depreciation_method_id;
  elsif tg_table_name = 'fixed_assets' then
    method_id := new.depreciation_method_id;
    account_ids := array_remove(array[new.asset_account_id, new.accumulated_depreciation_account_id, new.depreciation_expense_account_id], null);
  elsif tg_table_name in ('depreciation_schedules', 'depreciation_book_policies') then
    method_id := new.depreciation_method_id;
  end if;
  if method_id is not null and not exists (
    select 1 from depreciation_methods m where m.id = method_id and m.org_id = new.org_id and m.is_active
  ) then
    raise exception 'depreciation method must be active and belong to the tenant';
  end if;
  if cardinality(account_ids) > 0 and exists (
    select 1 from unnest(account_ids) wanted(id)
     where not exists (select 1 from accounts a where a.id = wanted.id and a.org_id = new.org_id and a.is_active and not a.is_summary)
  ) then
    raise exception 'fixed asset account override must be an active postable account in the tenant';
  end if;
  return new;
end $$;


--
-- Name: guard_recognition_schedule_line_financial_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_recognition_schedule_line_financial_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if old.journal_entry_id is not null then
    if new.schedule_id is distinct from old.schedule_id
       or new.period_id is distinct from old.period_id
       or new.sequence is distinct from old.sequence
       or new.planned_amount is distinct from old.planned_amount
       or new.recognized_amount is distinct from old.recognized_amount
       or new.journal_entry_id is distinct from old.journal_entry_id then
      raise exception
        'posted revenue-recognition schedule line financial history is immutable';
    end if;
  end if;

  if old.reversal_journal_entry_id is not null
     and new.reversal_journal_entry_id is distinct from old.reversal_journal_entry_id then
    raise exception
      'revenue-recognition reversal lineage is immutable';
  end if;
  return new;
end;
$$;


--
-- Name: intercompany_pair_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.intercompany_pair_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_from_type text;
  v_to_type text;
begin
  if new.from_subsidiary_id = new.to_subsidiary_id then
    raise exception 'intercompany subsidiaries must be different' using errcode = '23514';
  end if;
  if (select count(*) from subsidiaries s
       where s.org_id = new.org_id and s.id in (new.from_subsidiary_id, new.to_subsidiary_id)
         and s.is_active and not s.is_elimination) <> 2 then
    raise exception 'intercompany subsidiaries are invalid' using errcode = '23514';
  end if;
  select type into v_from_type from accounts
   where id = new.due_from_account_id and org_id = new.org_id
     and is_active and not is_summary and eliminate;
  select type into v_to_type from accounts
   where id = new.due_to_account_id and org_id = new.org_id
     and is_active and not is_summary and eliminate;
  if v_from_type is null or v_from_type not like 'asset\_%' escape '\' then
    raise exception 'due-from account must be an eliminable asset' using errcode = '23514';
  end if;
  if v_to_type is null or v_to_type not like 'liability\_%' escape '\' then
    raise exception 'due-to account must be an eliminable liability' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: inv_move_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inv_move_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'posted' and not openbooks_sandbox_wipe_allowed(old.org_id) then
      raise exception 'inventory movement % is posted and cannot be deleted', old.id;
    end if;
    return old;
  end if;
  if old.status = 'posted' and new.status = 'posted' then
    raise exception 'inventory movement % is posted and immutable', old.id;
  end if;
  return new;
end $$;


--
-- Name: inventory_lot_identity_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_lot_identity_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'lot identity and recall evidence cannot be deleted';
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.item_id IS DISTINCT FROM OLD.item_id
     OR NEW.lot_number IS DISTINCT FROM OLD.lot_number
     OR (OLD.expires_on IS NOT NULL
         AND NEW.expires_on IS DISTINCT FROM OLD.expires_on) THEN
    RAISE EXCEPTION 'lot identity is immutable; only a missing expiry may be completed';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: inventory_movement_tracking_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_movement_tracking_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_tracking text;
BEGIN
  SELECT profile.tracking
    INTO v_tracking
    FROM item_inventory_profiles profile
   WHERE profile.org_id = NEW.org_id
     AND profile.item_id = NEW.item_id;
  IF v_tracking IS NULL THEN
    RAISE EXCEPTION 'inventory movement item has no tenant-owned inventory profile'
      USING ERRCODE = '23514';
  END IF;

  IF v_tracking = 'none' THEN
    IF NEW.lot_id IS NOT NULL OR NEW.serial_id IS NOT NULL THEN
      RAISE EXCEPTION 'untracked inventory movement cannot carry lot or serial evidence'
        USING ERRCODE = '23514';
    END IF;
  ELSIF v_tracking = 'lot' THEN
    IF NEW.lot_id IS NULL OR NEW.serial_id IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM lots lot
       WHERE lot.id = NEW.lot_id
         AND lot.org_id = NEW.org_id
         AND lot.item_id = NEW.item_id
    ) THEN
      RAISE EXCEPTION 'lot-tracked movement requires a tenant/item-owned lot'
        USING ERRCODE = '23514';
    END IF;
  ELSIF v_tracking = 'serial' THEN
    IF NEW.serial_id IS NULL OR NEW.lot_id IS NOT NULL
       OR abs(NEW.quantity) <> 1
       OR NOT EXISTS (
         SELECT 1 FROM serials serial
          WHERE serial.id = NEW.serial_id
            AND serial.org_id = NEW.org_id
            AND serial.item_id = NEW.item_id
       ) THEN
      RAISE EXCEPTION 'serial-tracked movement requires one tenant/item-owned serial'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'unsupported inventory tracking policy %', v_tracking
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: inventory_provisional_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_provisional_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if current_setting('openbooks.sandbox_wipe',true)='on' then return old; end if;
  raise exception 'inventory provisional evidence is immutable';
end $$;


--
-- Name: inventory_serial_lifecycle_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.inventory_serial_lifecycle_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'serial identity and movement evidence cannot be deleted';
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id
     OR NEW.item_id IS DISTINCT FROM OLD.item_id
     OR NEW.serial_number IS DISTINCT FROM OLD.serial_number THEN
    RAISE EXCEPTION 'serial identity is immutable';
  END IF;
  IF NEW.status IS NOT DISTINCT FROM OLD.status
     AND NEW.current_stock_location_id IS NOT DISTINCT FROM OLD.current_stock_location_id THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'registered' AND NEW.status = 'in_stock'
     AND NEW.current_stock_location_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM inventory_movements movement
        WHERE movement.org_id = OLD.org_id
          AND movement.serial_id = OLD.id
          AND movement.kind = 'receipt'
          AND movement.quantity = 1
          AND movement.stock_location_id = NEW.current_stock_location_id
          AND movement.status = 'posted'
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'in_stock' AND NEW.status = 'shipped'
     AND NEW.current_stock_location_id IS NULL
     AND EXISTS (
       SELECT 1 FROM inventory_movements movement
        WHERE movement.org_id = OLD.org_id
          AND movement.serial_id = OLD.id
          AND movement.kind = 'issue'
          AND movement.quantity = -1
          AND movement.stock_location_id = OLD.current_stock_location_id
          AND movement.status = 'posted'
          AND NOT EXISTS (
            SELECT 1 FROM inventory_movements reversal
             WHERE reversal.org_id = movement.org_id
               AND reversal.reverses_movement_id = movement.id
          )
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'in_stock' AND NEW.status = 'in_stock'
     AND NEW.current_stock_location_id IS DISTINCT FROM OLD.current_stock_location_id
     AND (
       EXISTS (
         SELECT 1
           FROM inventory_movements outbound
           JOIN inventory_movements inbound
             ON inbound.org_id = outbound.org_id
            AND inbound.paired_movement_id = outbound.id
          WHERE outbound.org_id = OLD.org_id
            AND outbound.serial_id = OLD.id
            AND inbound.serial_id = OLD.id
            AND outbound.kind = 'transfer_out'
            AND inbound.kind = 'transfer_in'
            AND outbound.stock_location_id = OLD.current_stock_location_id
            AND inbound.stock_location_id = NEW.current_stock_location_id
            AND outbound.status = 'posted'
            AND inbound.status = 'posted'
       )
       OR EXISTS (
         SELECT 1
           FROM inventory_movements source_out
           JOIN inventory_movements source_in
             ON source_in.org_id = source_out.org_id
            AND source_in.paired_movement_id = source_out.id
           JOIN inventory_movements reversal_out
             ON reversal_out.org_id = source_out.org_id
            AND reversal_out.reverses_movement_id = source_out.id
           JOIN inventory_movements reversal_in
             ON reversal_in.org_id = source_in.org_id
            AND reversal_in.reverses_movement_id = source_in.id
          WHERE source_out.org_id = OLD.org_id
            AND source_out.serial_id = OLD.id
            AND source_in.serial_id = OLD.id
            AND source_in.stock_location_id = OLD.current_stock_location_id
            AND source_out.stock_location_id = NEW.current_stock_location_id
       )
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'shipped' AND NEW.status = 'in_stock'
     AND NEW.current_stock_location_id IS NOT NULL
     AND EXISTS (
       SELECT 1
         FROM inventory_movements source
         JOIN inventory_movements reversal
           ON reversal.org_id = source.org_id
          AND reversal.reverses_movement_id = source.id
        WHERE source.org_id = OLD.org_id
          AND source.serial_id = OLD.id
          AND source.kind = 'issue'
          AND source.stock_location_id = NEW.current_stock_location_id
          AND reversal.serial_id = OLD.id
          AND reversal.status = 'posted'
     ) THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'in_stock' AND NEW.status = 'returned'
     AND NEW.current_stock_location_id IS NULL
     AND EXISTS (
       SELECT 1
         FROM inventory_movements source
         JOIN inventory_movements reversal
           ON reversal.org_id = source.org_id
          AND reversal.reverses_movement_id = source.id
        WHERE source.org_id = OLD.org_id
          AND source.serial_id = OLD.id
          AND source.kind = 'receipt'
          AND source.stock_location_id = OLD.current_stock_location_id
          AND reversal.serial_id = OLD.id
          AND reversal.status = 'posted'
     ) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'serial lifecycle transition lacks matching posted inventory evidence';
END
$$;


--
-- Name: item_rate_book_assignments_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_rate_book_assignments_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not new.is_active then return new; end if;
  if exists (
    select 1
      from item_rate_book_assignments a
     where a.id <> new.id
       and a.org_id = new.org_id
       and a.is_active
       and a.customer_id is not distinct from new.customer_id
       and a.project_id is not distinct from new.project_id
       and a.department_id is not distinct from new.department_id
       and a.subsidiary_id is not distinct from new.subsidiary_id
       and a.location_id is not distinct from new.location_id
       and a.class_id is not distinct from new.class_id
       and a.rate_book_id = new.rate_book_id
       and a.rate_version_id is not distinct from new.rate_version_id
       and a.date_basis = new.date_basis
       and effective_date_ranges_overlap(coalesce(a.effective_from, '-infinity'::date), a.effective_to, coalesce(new.effective_from, '-infinity'::date), new.effective_to)
  ) then
    raise exception 'rate-book assignments overlap for the same assignment scope' using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: item_rate_versions_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_rate_versions_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.status <> 'active' then return new; end if;
  if exists (
    select 1
      from item_rate_versions v
     where v.id <> new.id
       and v.org_id = new.org_id
       and v.rate_book_id = new.rate_book_id
       and v.status = 'active'
       and effective_date_ranges_overlap(v.effective_from, v.effective_to, new.effective_from, new.effective_to)
  ) then
    raise exception 'active item rate versions overlap for rate book %', new.rate_book_id using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: je_check_posted_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.je_check_posted_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_sum numeric(19,4);
  v_bad record;
begin
  if new.status <> 'posted' then return null; end if;
  select coalesce(sum(amount), 0) into v_sum
    from journal_lines where entry_id = new.id;
  if v_sum <> 0 then
    raise exception 'posted journal entry % does not balance (sum = %)', new.id, v_sum
      using errcode = '23514';
  end if;
  select subsidiary_id, sum(amount) as total into v_bad
    from journal_lines where entry_id = new.id
   group by subsidiary_id having sum(amount) <> 0 limit 1;
  if found then
    raise exception 'posted journal entry % does not balance for subsidiary % (sum = %)',
      new.id, v_bad.subsidiary_id, v_bad.total using errcode = '23514';
  end if;
  if (select count(*) from journal_lines where entry_id = new.id) < 2 then
    raise exception 'posted journal entry % must contain at least two lines', new.id
      using errcode = '23514';
  end if;
  return null;
end $$;


--
-- Name: je_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.je_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(current_setting('openbooks.sandbox_wipe', true), 'off') = 'on' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if openbooks_sandbox_wipe_allowed(old.org_id) then return old; end if;
    -- Deleting a transaction removes its journal entry too. That is the one
    -- legitimate removal of a posted entry, done by the engine's guarded
    -- delete under the 'openbooks.amend' flag (after it has proven the delete
    -- is safe: open period, no applied payments, no downstream conversion).
    if old.status <> 'draft'
       and coalesce(current_setting('openbooks.amend', true), 'off') <> 'on' then
      raise exception 'journal entry % is % and cannot be deleted', old.id, old.status;
    end if;
    if old.status <> 'draft'
       and period_module_is_closed(old.org_id, old.period_id, old.book_id,
         nullif(to_jsonb(old)->>'subsidiary_id', '')::uuid, 'gl') then
      raise exception 'period is closed for GL posting';
    end if;
    return old;
  end if;

  -- A document-sourced entry is a DERIVED projection of its source document:
  -- entry = postingRules(document), re-materialized on every save. When
  -- 'openbooks.amend' is on (set only by the engine's materialize path), a
  -- posted entry's header may be regenerated in place. It normally requires an
  -- OPEN period; source replay can cross only source-owned imported locks. A reversed original is
  -- still posted ledger history, so it uses the same guarded path while
  -- remaining reversed. Balance + summary-account rules still apply.
  if old.status in ('posted', 'reversed') and new.status = old.status
     and coalesce(current_setting('openbooks.amend', true), 'off') = 'on' then
    if period_module_blocks_write(old.org_id, old.period_id, old.book_id,
         nullif(to_jsonb(old)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       or period_module_blocks_write(new.org_id, new.period_id, new.book_id,
         nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
      raise exception 'period is closed for GL posting';
    end if;
    return new;
  end if;

  if old.status = 'posted' and new.status = 'posted' then
    raise exception 'journal entry % is posted and immutable', old.id;
  end if;
  if old.status = 'reversed' then
    raise exception 'journal entry % is reversed and immutable', old.id;
  end if;

  -- draft -> posted: period must be open for GL
  if old.status = 'draft' and new.status = 'posted' then
    if period_module_blocks_write(new.org_id, new.period_id, new.book_id,
         nullif(to_jsonb(new)->>'subsidiary_id', '')::uuid, 'gl',
         coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       or exists (
         select 1 from journal_lines l
          where l.entry_id = new.id
            and period_module_blocks_write(new.org_id, new.period_id, new.book_id,
              nullif(to_jsonb(l)->>'subsidiary_id', '')::uuid, 'gl',
              coalesce(current_setting('openbooks.migration', true), 'off') = 'on')
       ) then
      raise exception 'period is closed for GL posting';
    end if;
    new.posted_at := now();
  end if;
  return new;
end $$;


--
-- Name: jl_check_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_check_account() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_summary boolean;
  v_active boolean;
  v_ccy text;
begin
  select is_summary, is_active, currency_restriction
    into v_summary, v_active, v_ccy
    from accounts where id = new.account_id;
  if not found then
    raise exception 'account % does not exist', new.account_id;
  end if;
  if v_summary then
    raise exception 'account % is a summary account and cannot be posted to', new.account_id;
  end if;
  -- Historical migration replays may post to accounts that are inactive
  -- TODAY but were active at the time. 'set local openbooks.migration = on'
  -- (transaction-scoped, requires direct DB access) relaxes ONLY this check;
  -- balance, immutability and summary-account rules always hold.
  if not v_active and coalesce(current_setting('openbooks.migration', true), 'off') <> 'on' then
    raise exception 'account % is inactive', new.account_id;
  end if;
  if v_ccy is not null and new.currency <> v_ccy then
    raise exception 'account % only accepts % postings', new.account_id, v_ccy;
  end if;
  return new;
end $$;


--
-- Name: jl_check_balanced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_check_balanced() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_entry uuid;
  v_old_entry uuid;
  v_sum numeric(19,4);
begin
  v_entry := case when tg_op = 'DELETE' then old.entry_id else new.entry_id end;
  v_old_entry := case when tg_op = 'UPDATE' then old.entry_id else null end;
  foreach v_entry in array array[v_entry, v_old_entry] loop
    if v_entry is null then continue; end if;
    select coalesce(sum(amount), 0) into v_sum
      from journal_lines where entry_id = v_entry;
    if v_sum <> 0 then
      raise exception 'journal entry % does not balance (sum = %)', v_entry, v_sum
        using errcode = '23514';
    end if;
  end loop;
  return null;
end $$;


--
-- Name: jl_check_balanced_by_subsidiary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_check_balanced_by_subsidiary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_entry uuid;
  v_new_entry uuid;
  v_old_entry uuid;
  v_bad record;
begin
  v_new_entry := case when tg_op = 'DELETE' then null else new.entry_id end;
  v_old_entry := case when tg_op in ('UPDATE', 'DELETE') then old.entry_id else null end;
  foreach v_entry in array array[v_new_entry, v_old_entry] loop
    if v_entry is null then continue; end if;
    select subsidiary_id, sum(amount) as total into v_bad
      from journal_lines where entry_id = v_entry
     group by subsidiary_id having sum(amount) <> 0 limit 1;
    if found then
      raise exception 'journal entry % does not balance for subsidiary % (sum = %)',
        v_entry, v_bad.subsidiary_id, v_bad.total using errcode = '23514';
    end if;
  end loop;
  return null;
end $$;


--
-- Name: jl_check_required_dimensions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_check_required_dimensions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_key text; v_required jsonb;
begin
  select required_dimensions into v_required from accounts
   where id = new.account_id and org_id = new.org_id;
  for v_key in select jsonb_array_elements_text(coalesce(v_required, '[]'::jsonb)) loop
    if (case v_key
      when 'subsidiary' then new.subsidiary_id is null
      when 'department' then new.department_id is null
      when 'project' then new.project_id is null
      when 'location' then new.location_id is null
      when 'class' then new.class_id is null
      when 'party' then new.party_id is null
      else not (coalesce(new.extra_dims, '{}'::jsonb) ? v_key)
    end) then
      raise exception 'account % requires segment %', new.account_id, v_key using errcode = '23514';
    end if;
  end loop;
  return new;
end $$;


--
-- Name: jl_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jl_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text;
  v_org uuid;
  v_period uuid;
  v_book uuid;
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  select status, org_id, period_id, book_id into v_status, v_org, v_period, v_book from journal_entries
    where id = coalesce(new.entry_id, old.entry_id);
  if v_status is distinct from 'draft' then
    -- Bank-reconciliation sign-off stamps reconciled_at / reconciliation_id
    -- on posted lines. That is bookkeeping metadata, but it is still permanent
    -- financial-control evidence: it may only transition once from entirely
    -- unset to an extant unsigned reconciliation that already claims the line.
    -- Clearing, retargeting, or partially stamping the evidence is forbidden.
    if tg_op = 'UPDATE'
       and to_jsonb(new) - 'reconciled_at' - 'reconciliation_id'
         = to_jsonb(old) - 'reconciled_at' - 'reconciliation_id'
    then
      if new.reconciled_at is not distinct from old.reconciled_at
         and new.reconciliation_id is not distinct from old.reconciliation_id then
        return new;
      end if;
      if old.reconciled_at is null
         and old.reconciliation_id is null
         and new.reconciled_at is not null
         and new.reconciliation_id is not null
         and exists (
           select 1
             from reconciliations r
            where r.id = new.reconciliation_id
              and r.org_id = new.org_id
              and r.status <> 'signed_off'
         )
         and exists (
           select 1
             from reconciliation_matches m
            where m.reconciliation_id = new.reconciliation_id
              and m.journal_line_id = new.id
              and m.org_id = new.org_id
         ) then
        return new;
      end if;
      raise exception 'journal-line reconciliation evidence is append-only';
    end if;
    -- Re-materializing posted ledger history's GL-Impact projection from its
    -- edited source document (engine-only 'openbooks.amend' flag). A reversed
    -- original remains reversed; a posted entry remains posted. Balance and
    -- account guards still fire on the amended lines.
    if v_status in ('posted', 'reversed')
       and coalesce(current_setting('openbooks.amend', true), 'off') = 'on' then
      if period_module_blocks_write(v_org, v_period, v_book,
           nullif(coalesce(to_jsonb(new), to_jsonb(old))->>'subsidiary_id', '')::uuid, 'gl',
           coalesce(current_setting('openbooks.migration', true), 'off') = 'on') then
        raise exception 'period is closed for GL posting';
      end if;
      return coalesce(new, old);
    end if;
    raise exception 'lines of a % journal entry are immutable', v_status;
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: labor_cost_rates_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.labor_cost_rates_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not new.is_active then return new; end if;
  if exists (
    select 1
      from labor_cost_rates r
     where r.id <> new.id
       and r.org_id = new.org_id
       and r.is_active
       and r.employee_party_id is not distinct from new.employee_party_id
       and lower(coalesce(r.job_title, '')) = lower(coalesce(new.job_title, ''))
       and r.trade_id is not distinct from new.trade_id
       and r.department_id is not distinct from new.department_id
       and r.subsidiary_id is not distinct from new.subsidiary_id
       and effective_date_ranges_overlap(r.effective_from, r.effective_to, new.effective_from, new.effective_to)
  ) then
    raise exception 'labor cost rates overlap for the same wage scope' using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: landed_cost_allocation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_allocation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'landed-cost allocation evidence is append-only';
  END IF;
  IF OLD.journal_entry_id IS NULL
     AND NEW.journal_entry_id IS NOT NULL
     AND (to_jsonb(NEW) - 'journal_entry_id' - 'updated_at' - 'updated_by')
       = (to_jsonb(OLD) - 'journal_entry_id' - 'updated_at' - 'updated_by') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'landed-cost allocation evidence is immutable';
END
$$;


--
-- Name: landed_cost_voucher_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_voucher_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'draft'
       OR openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'posted landed-cost vouchers cannot be deleted';
  END IF;
  IF OLD.status = 'draft' THEN RETURN NEW; END IF;
  IF OLD.status = 'posted'
     AND NEW.status = 'void'
     AND NEW.org_id = OLD.org_id
     AND NEW.document_number = OLD.document_number
     AND NEW.amount = OLD.amount
     AND NEW.basis = OLD.basis
     AND NEW.freight_account_id = OLD.freight_account_id
     AND NEW.source_document_line_id IS NOT DISTINCT FROM OLD.source_document_line_id
     AND NEW.subsidiary_id = OLD.subsidiary_id
     AND NEW.voucher_date = OLD.voucher_date
     AND NEW.journal_entry_id = OLD.journal_entry_id
     AND NEW.memo IS NOT DISTINCT FROM OLD.memo
     AND NEW.created_at = OLD.created_at
     AND NEW.created_by IS NOT DISTINCT FROM OLD.created_by
     AND NEW.reversal_journal_entry_id IS NOT NULL
     AND NEW.voided_at IS NOT NULL
     AND NEW.voided_by IS NOT NULL
     AND length(btrim(NEW.void_reason)) BETWEEN 5 AND 500 THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'posted and void landed-cost vouchers are immutable';
END
$$;


--
-- Name: landed_cost_voucher_target_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.landed_cost_voucher_target_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  parent_status text;
  parent_org uuid;
BEGIN
  SELECT status, org_id
    INTO parent_status, parent_org
    FROM landed_cost_vouchers
   WHERE id = coalesce(NEW.voucher_id, OLD.voucher_id);
  IF TG_OP = 'DELETE' AND parent_status IS NULL THEN RETURN OLD; END IF;
  IF parent_status IS NULL
     OR parent_org IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'landed-cost target must reference a tenant-owned voucher';
  END IF;
  IF parent_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of a posted landed-cost voucher are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: ob_rebase(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ob_rebase(old uuid, seed uuid) RETURNS uuid
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    select md5(seed::text || ':' || old::text)::uuid
$$;


--
-- Name: openbooks_bank_rule_criteria_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_criteria_is_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  account_id text;
BEGIN
  IF jsonb_typeof(value) <> 'object'
     OR value->>'version' <> '2'
     OR octet_length(value::text) > 100000
     OR NOT openbooks_bank_rule_group_is_valid(value->'match') THEN
    RETURN false;
  END IF;
  IF value ? 'accountScope' THEN
    IF jsonb_typeof(value->'accountScope') <> 'array' THEN
      RETURN false;
    END IF;
    FOR account_id IN SELECT entry FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)
    LOOP
      IF account_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF (SELECT count(*) <> count(DISTINCT entry) FROM jsonb_array_elements_text(value->'accountScope') AS entries(entry)) THEN
      RETURN false;
    END IF;
  END IF;
  RETURN true;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_rule_group_is_valid(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_group_is_valid(value jsonb, depth integer DEFAULT 0) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  rule jsonb;
  field_name text;
  operator_name text;
  scalar_value text;
  numeric_value numeric;
  lower_bound numeric;
  upper_bound numeric;
BEGIN
  IF depth > 4
     OR jsonb_typeof(value) <> 'object'
     OR value->>'combinator' NOT IN ('and', 'or')
     OR jsonb_typeof(value->'rules') <> 'array'
     OR jsonb_array_length(value->'rules') NOT BETWEEN 1 AND 40 THEN
    RETURN false;
  END IF;

  FOR rule IN SELECT element FROM jsonb_array_elements(value->'rules') AS elements(element)
  LOOP
    IF jsonb_typeof(rule) <> 'object' THEN
      RETURN false;
    END IF;
    IF rule ? 'rules' THEN
      IF NOT openbooks_bank_rule_group_is_valid(rule, depth + 1) THEN
        RETURN false;
      END IF;
      CONTINUE;
    END IF;

    field_name := rule->>'field';
    operator_name := rule->>'op';
    scalar_value := rule->>'value';

    IF field_name IN ('description', 'payee', 'anyText', 'reference') THEN
      IF operator_name NOT IN ('contains', 'notContains', 'equals', 'startsWith', 'endsWith', 'isBlank')
         OR (operator_name <> 'isBlank' AND (jsonb_typeof(rule->'value') <> 'string' OR btrim(scalar_value) = '' OR length(scalar_value) > 200)) THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'flow' THEN
      IF operator_name <> 'is' OR scalar_value NOT IN ('in', 'out', 'any') THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'source' THEN
      IF operator_name <> 'equals' OR jsonb_typeof(rule->'value') <> 'string'
         OR btrim(scalar_value) = '' OR length(scalar_value) > 40 THEN
        RETURN false;
      END IF;
    ELSIF field_name = 'amount' THEN
      IF operator_name NOT IN ('eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'between') THEN
        RETURN false;
      END IF;
      IF operator_name = 'between' THEN
        IF jsonb_typeof(rule->'value') <> 'array'
           OR jsonb_array_length(rule->'value') <> 2
           OR jsonb_typeof(rule->'value'->0) <> 'number'
           OR jsonb_typeof(rule->'value'->1) <> 'number' THEN
          RETURN false;
        END IF;
        lower_bound := (rule->'value'->>0)::numeric;
        upper_bound := (rule->'value'->>1)::numeric;
        IF lower_bound < 0 OR upper_bound < lower_bound THEN
          RETURN false;
        END IF;
      ELSE
        IF jsonb_typeof(rule->'value') <> 'number' THEN
          RETURN false;
        END IF;
        numeric_value := scalar_value::numeric;
        IF numeric_value < 0 THEN
          RETURN false;
        END IF;
      END IF;
    ELSIF field_name = 'date' THEN
      IF operator_name = 'withinDays' THEN
        IF jsonb_typeof(rule->'value') <> 'number' OR scalar_value::numeric <= 0 THEN
          RETURN false;
        END IF;
      ELSIF operator_name IN ('on', 'before', 'after') THEN
        IF jsonb_typeof(rule->'value') <> 'string'
           OR scalar_value !~ '^\d{4}-\d{2}-\d{2}$'
           OR to_char(scalar_value::date, 'YYYY-MM-DD') <> scalar_value THEN
          RETURN false;
        END IF;
      ELSE
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;
  END LOOP;
  RETURN true;
EXCEPTION WHEN invalid_text_representation OR datetime_field_overflow OR numeric_value_out_of_range THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_rule_outcome_is_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_rule_outcome_is_valid(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
  line jsonb;
  portion jsonb;
  optional_id text;
  remainder_count integer := 0;
BEGIN
  IF jsonb_typeof(value) <> 'object' OR octet_length(value::text) > 100000 THEN
    RETURN false;
  END IF;
  IF value->>'action' = 'exclude' THEN
    RETURN value = '{"action":"exclude"}'::jsonb;
  END IF;
  IF value->>'action' <> 'categorize'
     OR value->>'version' <> '2'
     OR value->>'mode' NOT IN ('auto', 'suggest')
     OR jsonb_typeof(value->'lines') <> 'array'
     OR jsonb_array_length(value->'lines') NOT BETWEEN 1 AND 20 THEN
    RETURN false;
  END IF;

  IF value ? 'partyId' AND coalesce(value->>'partyId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN false;
  END IF;
  IF value ? 'memo' AND (jsonb_typeof(value->'memo') <> 'string' OR btrim(value->>'memo') = '' OR length(value->>'memo') > 300) THEN
    RETURN false;
  END IF;

  FOR line IN SELECT element FROM jsonb_array_elements(value->'lines') AS elements(element)
  LOOP
    IF jsonb_typeof(line) <> 'object'
       OR coalesce(line->>'accountId', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR jsonb_typeof(line->'portion') <> 'object' THEN
      RETURN false;
    END IF;
    portion := line->'portion';
    IF portion->>'kind' = 'remainder' THEN
      remainder_count := remainder_count + 1;
    ELSIF portion->>'kind' = 'percent' THEN
      IF jsonb_typeof(portion->'value') <> 'number'
         OR (portion->>'value')::numeric <= 0
         OR (portion->>'value')::numeric > 100 THEN
        RETURN false;
      END IF;
    ELSIF portion->>'kind' = 'fixed' THEN
      IF jsonb_typeof(portion->'value') <> 'number' OR (portion->>'value')::numeric <= 0 THEN
        RETURN false;
      END IF;
    ELSE
      RETURN false;
    END IF;

    FOREACH optional_id IN ARRAY ARRAY['partyId', 'departmentId', 'projectId', 'locationId', 'classId', 'taxCodeId']
    LOOP
      IF line ? optional_id
         AND coalesce(line->>optional_id, '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN false;
      END IF;
    END LOOP;
    IF line ? 'description'
       AND (jsonb_typeof(line->'description') <> 'string' OR btrim(line->>'description') = '' OR length(line->>'description') > 200) THEN
      RETURN false;
    END IF;
  END LOOP;
  RETURN remainder_count <= 1;
EXCEPTION WHEN OTHERS THEN
  RETURN false;
END;
$_$;


--
-- Name: openbooks_bank_statement_line_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_bank_statement_line_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF tg_op = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(old.org_id) THEN
      RETURN old;
    END IF;
    RAISE EXCEPTION 'imported bank statement lines are immutable';
  END IF;
  IF tg_op = 'INSERT' THEN
    RETURN new;
  END IF;
  IF to_jsonb(new)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'updated_at' - 'updated_by'
     <> to_jsonb(old)
       - 'match_status' - 'exclusion_reason' - 'excluded_at' - 'excluded_by'
       - 'updated_at' - 'updated_by' THEN
    RAISE EXCEPTION 'imported bank statement content is immutable';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM reconciliation_matches m
      JOIN reconciliations r ON r.id = m.reconciliation_id
     WHERE m.statement_line_id = old.id
       AND m.org_id = old.org_id
       AND r.status = 'signed_off'
  ) OR EXISTS (
    SELECT 1
      FROM reconciliations r
     WHERE r.org_id = old.org_id
       AND r.account_id = old.account_id
       AND r.currency = old.currency
       AND r.status = 'signed_off'
       AND r.through_date >= old.posted_on
       AND old.match_status = 'excluded'
  ) THEN
    RAISE EXCEPTION 'signed-off bank statement evidence is immutable';
  END IF;
  IF new.match_status = 'matched'
     AND NOT EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'matched bank statement line requires reconciliation-match evidence';
  END IF;
  IF new.match_status <> 'matched'
     AND EXISTS (
       SELECT 1 FROM reconciliation_matches m
        WHERE m.statement_line_id = new.id AND m.org_id = new.org_id
     ) THEN
    RAISE EXCEPTION 'bank statement line with match evidence must remain matched';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: openbooks_gl_activity_apply(p_org uuid, p_account uuid, p_month date, p_subsidiary uuid, p_debit numeric, p_credit numeric, p_count bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_apply(p_org uuid, p_account uuid, p_month date, p_subsidiary uuid, p_debit numeric, p_credit numeric, p_count bigint) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, month, subsidiary_id, debit_total, credit_total, line_count)
  values (p_org, p_account, p_month, p_subsidiary, p_debit, p_credit, p_count)
  on conflict (org_id, account_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_entry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_old_in boolean;
  v_new_in boolean;
  v_old_month date;
  v_new_month date;
begin
  -- Wipes delete the summary rows themselves; per-row maintenance during a
  -- wipe is pure waste.
  if coalesce(current_setting('openbooks.sandbox_wipe', true), 'off') = 'on' then
    return null;
  end if;
  if tg_op = 'INSERT' then
    -- Bulk copies (sandbox clone, backup restore, migration) may insert an
    -- already-posted entry before or after its lines; aggregating whatever
    -- lines exist right now composes with the per-line trigger to count each
    -- line exactly once in either order.
    if new.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(new.id, new.org_id, date_trunc('month', new.posting_date)::date, 1);
    end if;
    return null;
  end if;
  if tg_op = 'DELETE' then
    if old.status in ('posted', 'reversed') then
      perform openbooks_gl_activity_entry_delta(old.id, old.org_id, date_trunc('month', old.posting_date)::date, -1);
    end if;
    return null;
  end if;
  v_old_in := old.status in ('posted', 'reversed');
  v_new_in := new.status in ('posted', 'reversed');
  v_old_month := date_trunc('month', old.posting_date)::date;
  v_new_month := date_trunc('month', new.posting_date)::date;
  if v_old_in and not v_new_in then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1);
  elsif v_new_in and not v_old_in then
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  elsif v_old_in and v_new_in and v_old_month <> v_new_month then
    perform openbooks_gl_activity_entry_delta(old.id, old.org_id, v_old_month, -1);
    perform openbooks_gl_activity_entry_delta(new.id, new.org_id, v_new_month, 1);
  end if;
  return null;
end $$;


--
-- Name: openbooks_gl_activity_entry_delta(p_entry uuid, p_org uuid, p_month date, p_sign integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_entry_delta(p_entry uuid, p_org uuid, p_month date, p_sign integer) RETURNS void
    LANGUAGE sql
    AS $$
  insert into gl_month_activity as g (org_id, account_id, month, subsidiary_id, debit_total, credit_total, line_count)
  select p_org, l.account_id, p_month, l.subsidiary_id,
         p_sign * coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0),
         p_sign * coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0),
         p_sign * count(*)
    from journal_lines l
   where l.entry_id = p_entry
   group by l.account_id, l.subsidiary_id
   order by l.account_id, l.subsidiary_id
  on conflict (org_id, account_id, month, subsidiary_id) do update
    set debit_total = g.debit_total + excluded.debit_total,
        credit_total = g.credit_total + excluded.credit_total,
        line_count = g.line_count + excluded.line_count;
$$;


--
-- Name: openbooks_gl_activity_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_status text;
  v_date date;
  v_org uuid;
  v_month date;
begin
  if coalesce(current_setting('openbooks.sandbox_wipe', true), 'off') = 'on' then
    return null;
  end if;
  if tg_op = 'UPDATE' and new.entry_id is distinct from old.entry_id then
    -- A line never legally moves between entries, but if it ever did the
    -- delta must split across both parents.
    select status, posting_date, org_id into v_status, v_date, v_org from journal_entries where id = old.entry_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, old.account_id, v_month, old.subsidiary_id,
        -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
    end if;
    select status, posting_date, org_id into v_status, v_date, v_org from journal_entries where id = new.entry_id;
    if v_status in ('posted', 'reversed') then
      v_month := date_trunc('month', v_date)::date;
      perform openbooks_gl_activity_apply(v_org, new.account_id, v_month, new.subsidiary_id,
        greatest(new.amount, 0), greatest(-new.amount, 0), 1);
    end if;
    return null;
  end if;
  select status, posting_date, org_id into v_status, v_date, v_org
    from journal_entries where id = coalesce(new.entry_id, old.entry_id);
  -- Draft edits are free; a missing parent means a bulk copy will account for
  -- this line when the entry row arrives (entry-INSERT aggregation).
  if v_status is null or v_status not in ('posted', 'reversed') then
    return null;
  end if;
  v_month := date_trunc('month', v_date)::date;
  if tg_op in ('UPDATE', 'DELETE') then
    perform openbooks_gl_activity_apply(v_org, old.account_id, v_month, old.subsidiary_id,
      -greatest(old.amount, 0), -greatest(-old.amount, 0), -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    perform openbooks_gl_activity_apply(v_org, new.account_id, v_month, new.subsidiary_id,
      greatest(new.amount, 0), greatest(-new.amount, 0), 1);
  end if;
  return null;
end $$;


--
-- Name: openbooks_gl_activity_rebuild(p_org uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_rebuild(p_org uuid) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
declare
  v_count bigint;
begin
  delete from gl_month_activity where org_id = p_org;
  insert into gl_month_activity (org_id, account_id, month, subsidiary_id, debit_total, credit_total, line_count)
  select e.org_id, l.account_id, date_trunc('month', e.posting_date)::date, l.subsidiary_id,
         coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0),
         coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0),
         count(*)
    from journal_lines l
    join journal_entries e on e.id = l.entry_id
   where e.org_id = p_org and l.org_id = p_org and e.status in ('posted', 'reversed')
   group by e.org_id, l.account_id, date_trunc('month', e.posting_date)::date, l.subsidiary_id;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


--
-- Name: openbooks_gl_activity_verify(p_org uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_gl_activity_verify(p_org uuid) RETURNS TABLE(account_id uuid, month date, subsidiary_id uuid, summary_debit numeric, ledger_debit numeric, summary_credit numeric, ledger_credit numeric)
    LANGUAGE sql
    AS $$
  with ledger as (
    select l.account_id, date_trunc('month', e.posting_date)::date as month, l.subsidiary_id,
           coalesce(sum(case when l.amount > 0 then l.amount else 0 end), 0) as debit_total,
           coalesce(sum(case when l.amount < 0 then -l.amount else 0 end), 0) as credit_total
      from journal_lines l
      join journal_entries e on e.id = l.entry_id
     where e.org_id = p_org and l.org_id = p_org and e.status in ('posted', 'reversed')
     group by 1, 2, 3
  ), summary as (
    select g.account_id, g.month, g.subsidiary_id, g.debit_total, g.credit_total
      from gl_month_activity g where g.org_id = p_org
       and (g.debit_total <> 0 or g.credit_total <> 0 or g.line_count <> 0)
  )
  select coalesce(l.account_id, s.account_id), coalesce(l.month, s.month),
         coalesce(l.subsidiary_id, s.subsidiary_id),
         coalesce(s.debit_total, 0), coalesce(l.debit_total, 0),
         coalesce(s.credit_total, 0), coalesce(l.credit_total, 0)
    from ledger l
    full outer join summary s
      on s.account_id = l.account_id and s.month = l.month and s.subsidiary_id = l.subsidiary_id
   where coalesce(s.debit_total, 0) <> coalesce(l.debit_total, 0)
      or coalesce(s.credit_total, 0) <> coalesce(l.credit_total, 0);
$$;


--
-- Name: openbooks_je_cascade_posting_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_je_cascade_posting_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(current_setting('openbooks.sandbox_wipe', true), 'off') = 'on' then
    return null;
  end if;
  update journal_lines
     set posting_date = new.posting_date
   where entry_id = new.id
     and posting_date is distinct from new.posting_date;
  return null;
end $$;


--
-- Name: openbooks_jl_stamp_posting_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_jl_stamp_posting_date() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  v_date date;
begin
  select posting_date into v_date from journal_entries where id = new.entry_id;
  -- A bulk copy may insert lines before their entry; the entry-side trigger
  -- fills those in when it arrives.
  new.posting_date := v_date;
  return new;
end $$;


--
-- Name: openbooks_guard_ap_capture_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'AP capture evidence is append-only';
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_blob(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_blob() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM file_versions fv
    JOIN ap_capture_items ci ON ci.file_id = fv.file_id
    WHERE fv.id = OLD.version_id
  ) THEN
    RAISE EXCEPTION 'AP capture source blobs are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = OLD.id) THEN
    RAISE EXCEPTION 'AP capture source files are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_ap_capture_source_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_ap_capture_source_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE target_file_id uuid;
BEGIN
  target_file_id := CASE WHEN TG_OP = 'INSERT' THEN NEW.file_id ELSE OLD.file_id END;
  IF EXISTS (SELECT 1 FROM ap_capture_items WHERE file_id = target_file_id) THEN
    RAISE EXCEPTION 'AP capture source versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_budget_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_budget_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  row_data budget_lines%rowtype;
  scenario_org uuid;
  scenario_year integer;
  scenario_status text;
begin
  row_data := case when tg_op = 'DELETE' then old else new end;
  select org_id, fiscal_year, status
    into scenario_org, scenario_year, scenario_status
    from budget_scenarios where id = row_data.scenario_id;
  -- During an ON DELETE CASCADE, PostgreSQL removes the parent scenario before
  -- firing the child row's delete trigger. The line was already protected by
  -- the scenario's draft-only delete guard, so allow that cascade to finish.
  if tg_op = 'DELETE' and scenario_org is null then return old; end if;
  if scenario_org is null or scenario_org <> row_data.org_id then
    raise exception 'budget line scenario must belong to the tenant';
  end if;
  if scenario_status <> 'draft' then
    raise exception 'budget lines are immutable outside draft status';
  end if;
  if tg_op = 'DELETE' then return old; end if;

  if not exists (
    select 1 from accounts a
     where a.id = new.account_id and a.org_id = new.org_id and a.is_active and not a.is_summary
  ) then
    raise exception 'budget account must be an active posting account in the tenant';
  end if;
  if not exists (
    select 1 from accounting_periods p
     where p.id = new.period_id and p.org_id = new.org_id
       and p.fiscal_year = scenario_year and not p.is_adjustment
  ) then
    raise exception 'budget period must belong to the scenario fiscal year and tenant';
  end if;
  if new.department_id is not null and not exists (
    select 1 from departments d where d.id = new.department_id and d.org_id = new.org_id
  ) then raise exception 'budget department must belong to the tenant'; end if;
  if new.project_id is not null and not exists (
    select 1 from projects p where p.id = new.project_id and p.org_id = new.org_id
  ) then raise exception 'budget project must belong to the tenant'; end if;
  if new.location_id is not null and not exists (
    select 1 from locations l where l.id = new.location_id and l.org_id = new.org_id
  ) then raise exception 'budget location must belong to the tenant'; end if;
  if new.class_id is not null and not exists (
    select 1 from classes c where c.id = new.class_id and c.org_id = new.org_id
  ) then raise exception 'budget class must belong to the tenant'; end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_budget_scenario(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_budget_scenario() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'only draft budget scenarios may be deleted';
    end if;
    return old;
  end if;

  if not exists (
    select 1 from accounting_books b
     where b.id = new.book_id and b.org_id = new.org_id and b.is_active
  ) then
    raise exception 'budget scenario book must be active and belong to the tenant';
  end if;

  if tg_op = 'UPDATE' then
    if new.revision <> old.revision + 1 then
      raise exception 'budget scenario revision must increment by exactly one';
    end if;
    if old.status <> 'draft' and (
      new.name is distinct from old.name or
      new.description is distinct from old.description or
      new.book_id is distinct from old.book_id or
      new.fiscal_year is distinct from old.fiscal_year or
      new.kind is distinct from old.kind
    ) then
      raise exception 'only draft budget metadata may be edited';
    end if;
    if new.status is distinct from old.status and not (
      (old.status = 'draft' and new.status in ('pending_approval', 'archived')) or
      (old.status = 'pending_approval' and new.status in ('draft', 'approved', 'archived')) or
      (old.status = 'approved' and new.status = 'archived')
    ) then
      raise exception 'invalid budget status transition: % -> %', old.status, new.status;
    end if;
  end if;

  if new.status in ('pending_approval', 'approved') and not exists (
    select 1 from budget_lines bl
     where bl.scenario_id = new.id and bl.org_id = new.org_id and bl.amount <> 0
  ) then
    raise exception 'a submitted or approved budget must contain at least one non-zero line';
  end if;
  if new.submitted_by is not null and not exists (
    select 1 from users u where u.id = new.submitted_by and u.org_id = new.org_id
  ) then raise exception 'budget submitter must belong to the tenant'; end if;
  if new.approved_by is not null and not exists (
    select 1 from users u where u.id = new.approved_by and u.org_id = new.org_id
  ) then raise exception 'budget approver must belong to the tenant'; end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_depreciation_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_depreciation_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  posted boolean;
begin
  if current_setting('openbooks.sandbox_wipe', true) = 'on' then return coalesce(new, old); end if;
  if tg_op = 'DELETE' then
    raise exception 'depreciation input evidence is append-preserved';
  end if;

  select exists (
    select 1 from depreciation_schedule_lines
     where input_id = old.id and posted_amount is not null
  ) into posted;
  if posted then
    raise exception 'posted depreciation input evidence is immutable';
  end if;

  if old.voided_at is not null
     or new.voided_at is null
     or new.voided_by is null
     or new.org_id is distinct from old.org_id
     or new.schedule_id is distinct from old.schedule_id
     or new.period_id is distinct from old.period_id
     or new.kind is distinct from old.kind
     or new.manual_amount is distinct from old.manual_amount
     or new.production_units is distinct from old.production_units
     or new.memo is distinct from old.memo
     or new.evidence_file_id is distinct from old.evidence_file_id
     or new.supersedes_input_id is distinct from old.supersedes_input_id
     or new.created_at is distinct from old.created_at
     or new.created_by is distinct from old.created_by then
    raise exception 'depreciation input evidence may only be voided before posting';
  end if;
  return new;
end;
$$;


--
-- Name: openbooks_guard_finished_ap_capture_run(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_finished_ap_capture_run() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' OR OLD.status <> 'running' THEN
    RAISE EXCEPTION 'Finished AP capture runs are immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: openbooks_guard_pay_run_bank_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_pay_run_bank_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'payroll bank files are immutable evidence and cannot be deleted';
  END IF;
  IF NEW.id <> OLD.id
     OR NEW.org_id <> OLD.org_id
     OR NEW.pay_run_document_id <> OLD.pay_run_document_id
     OR NEW.payment_bank_profile_id <> OLD.payment_bank_profile_id
     OR NEW.format <> OLD.format
     OR NEW.sequence_number <> OLD.sequence_number
     OR NEW.file_number <> OLD.file_number
     OR NEW.sequence_value <> OLD.sequence_value
     OR NEW.file_creation_number IS DISTINCT FROM OLD.file_creation_number
     OR NEW.file_id_modifier IS DISTINCT FROM OLD.file_id_modifier
     OR NEW.filename <> OLD.filename
     OR NEW.content_hash <> OLD.content_hash
     OR NEW.size_bytes <> OLD.size_bytes
     OR NEW.file_id <> OLD.file_id
     OR NEW.file_version_id <> OLD.file_version_id
     OR NEW.entry_count <> OLD.entry_count
     OR NEW.control_total <> OLD.control_total
     OR NEW.currency <> OLD.currency
     OR NEW.excluded_cheque::text <> OLD.excluded_cheque::text
     OR NEW.excluded_total <> OLD.excluded_total
     OR NEW.generated_at <> OLD.generated_at THEN
    RAISE EXCEPTION 'payroll bank file % is immutable: regenerate to produce a new artifact', OLD.file_number;
  END IF;
  IF NEW.release_count < OLD.release_count THEN
    RAISE EXCEPTION 'payroll bank file release history cannot be rewound';
  END IF;
  IF OLD.status = 'superseded' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION 'a superseded payroll bank file cannot be reinstated';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_blob(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_blob() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_version_id = OLD.version_id
  ) THEN
    RAISE EXCEPTION 'payroll bank file blobs are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_file(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_file() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_id = OLD.id) THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'payroll bank files cannot be deleted from the cabinet';
    END IF;
    -- Renaming, moving, retiring or re-pointing the current version would all
    -- change what a later download returns.
    IF NEW.name <> OLD.name OR NEW.folder_id <> OLD.folder_id
       OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
       OR NEW.current_version_id IS DISTINCT FROM OLD.current_version_id
       OR NEW.is_inactive <> OLD.is_inactive THEN
      RAISE EXCEPTION 'payroll bank files are immutable';
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_guard_payroll_bank_file_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_guard_payroll_bank_file_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.pay_run_bank_files f WHERE f.file_version_id = OLD.id
  ) THEN
    RAISE EXCEPTION 'payroll bank file versions are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: openbooks_query_org_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_query_org_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  resolved_org_id uuid;
begin
  execute 'select org_id from pg_temp.openbooks_query_context limit 1'
    into resolved_org_id;
  return resolved_org_id;
exception
  when undefined_table then return null;
end;
$$;


--
-- Name: openbooks_reconciliation_match_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_reconciliation_match_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_reconciliation_id uuid := coalesce(new.reconciliation_id, old.reconciliation_id);
  target_org_id uuid := coalesce(new.org_id, old.org_id);
  parent_status text;
BEGIN
  IF tg_op = 'DELETE' AND openbooks_sandbox_wipe_allowed(old.org_id) THEN
    RETURN old;
  END IF;
  SELECT status
    INTO parent_status
    FROM reconciliations
   WHERE id = target_reconciliation_id
     AND org_id = target_org_id;
  IF parent_status IS NULL THEN
    RAISE EXCEPTION 'reconciliation match parent must belong to the tenant';
  END IF;
  IF parent_status = 'signed_off' THEN
    RAISE EXCEPTION 'signed-off reconciliation matches are immutable';
  END IF;
  IF tg_op = 'UPDATE'
     AND (
       new.org_id IS DISTINCT FROM old.org_id
       OR new.reconciliation_id IS DISTINCT FROM old.reconciliation_id
       OR new.statement_line_id IS DISTINCT FROM old.statement_line_id
       OR new.journal_line_id IS DISTINCT FROM old.journal_line_id
       OR new.created_at IS DISTINCT FROM old.created_at
       OR new.created_by IS DISTINCT FROM old.created_by
     ) THEN
    RAISE EXCEPTION 'reconciliation match identity is immutable';
  END IF;
  IF tg_op <> 'DELETE' THEN
    IF NOT EXISTS (
      SELECT 1
        FROM reconciliations r
        JOIN bank_statement_lines l
          ON l.id = new.statement_line_id
         AND l.org_id = r.org_id
         AND l.account_id = r.account_id
         AND l.currency = r.currency
         AND l.posted_on <= r.through_date
        JOIN journal_lines jl
          ON jl.id = new.journal_line_id
         AND jl.org_id = r.org_id
         AND jl.account_id = r.account_id
         AND jl.currency = r.currency
        JOIN journal_entries je
          ON je.id = jl.entry_id
         AND je.status IN ('posted', 'reversed')
         AND je.posting_date <= r.through_date
       WHERE r.id = new.reconciliation_id
         AND r.org_id = new.org_id
         AND r.status <> 'signed_off'
         AND jl.reconciled_at IS NULL
    ) THEN
      RAISE EXCEPTION 'reconciliation match violates tenant, account, currency, cutoff, or journal availability';
    END IF;
  END IF;
  RETURN coalesce(new, old);
END;
$$;


--
-- Name: openbooks_refresh_query_catalog(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_refresh_query_catalog() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  relation_name text;
  has_org_id boolean;
  global_relations constant text[] := array['currencies'];
  safe_relations constant text[] := array[
    'account_group_members', 'account_groups', 'accounting_books',
    'accounting_periods', 'accounts', 'addresses', 'allocation_rule_targets',
    'allocation_rules', 'allocation_runs', 'applications', 'asset_categories',
    'asset_events', 'bank_match_rules', 'bank_statement_lines', 'bank_statements',
    'billing_request_field_tickets', 'billing_requests', 'billing_schedules',
    'bom_components', 'budget_lines', 'budget_scenarios', 'cam_allocations',
    'cam_pools', 'change_orders',
    'charge_rate_components', 'classes', 'close_automation_executions',
    'close_events', 'close_exceptions', 'close_reopen_requests',
    'close_reporting_packages', 'close_run_tasks', 'close_runs', 'close_signoffs',
    'close_task_evidence', 'compliance_classes', 'compliance_records',
    'compliance_release_checks', 'compliance_requirements', 'compliance_waivers',
    'consolidated_fx_rates', 'contacts', 'cost_layer_consumptions',
    'cost_layer_weights', 'cost_layers', 'crm_account_assignment_events',
    'crm_account_profiles', 'crm_account_stage_events', 'crm_account_statuses',
    'crm_activities', 'crm_activity_links', 'crm_activity_participants',
    'crm_forecast_snapshots', 'crm_lead_sources', 'crm_opportunities',
    'crm_opportunity_documents', 'crm_opportunity_lines',
    'crm_opportunity_stage_events', 'crm_opportunity_statuses',
    'crm_opportunity_team_members', 'crm_sales_quotas', 'crm_sales_team_members',
    'crm_sales_teams', 'crm_sales_territories', 'currencies', 'departments',
    'depreciation_book_policies', 'depreciation_inputs', 'depreciation_methods',
    'depreciation_schedule_lines', 'depreciation_schedules',
    'document_line_tax_components', 'document_lines', 'document_links', 'documents',
    'dunning_log', 'entitlement_ledger',
    'entitlement_plan_limits', 'entitlement_plans', 'entitlement_service_tiers',
    'equipment_units', 'fair_value_prices',
    'field_ticket_labor_lines', 'field_ticket_labor_snapshots',
    'field_ticket_signatures', 'field_tickets', 'fiscal_calendars', 'fixed_assets',
    'fx_rates', 'gl_month_activity', 'income_tax_rates', 'intercompany_pairs',
    'inventory_movements',
    'inventory_provisional_costs', 'inventory_provisional_settlements',
    'invoice_backups', 'item_inventory_profiles', 'item_rate_book_assignments',
    'item_rate_books', 'item_rate_lines', 'item_rate_profiles', 'item_rate_versions',
    'items', 'journal_entries', 'journal_lines', 'labor_cost_rates',
    'labor_rate_adjustment_targets', 'labor_rate_adjustments', 'labor_rate_terms',
    'labor_rate_version_policies', 'labor_rate_version_scopes',
    'landed_cost_allocations', 'landed_cost_voucher_targets', 'landed_cost_vouchers',
    'lease_charges', 'lease_escalations', 'lease_schedule_lines', 'lien_waivers',
    'locations', 'lots', 'managed_properties', 'overhead_rates',
    'ownership_consolidation_entries', 'ownership_consolidation_runs',
    'party_subsidiaries', 'pay_application_lines', 'pay_applications',
    'payment_events', 'payment_remittances', 'payment_run_items', 'payment_runs',
    'payment_schedules', 'payment_settlements', 'payment_surcharge_rules',
    'payment_terms', 'performance_obligations', 'period_locks',
    'project_financial_adjustments', 'project_financial_profile_versions',
    'project_overhead_adjustments', 'project_tasks', 'project_types', 'projects',
    'property_leases', 'property_units',
    'recognition_rules', 'recognition_schedule_lines', 'recognition_schedules',
    'reconciliation_matches', 'reconciliations', 'recurring_schedules',
    'revenue_contracts', 'schedule_baseline_tasks', 'schedule_baselines',
    'schedule_calendars', 'schedule_dependencies', 'schedule_resources',
    'schedule_task_assignments', 'security_deposit_transactions',
    'segment_definitions', 'segment_values', 'serials',
    'sov_lines', 'stock_count_lines', 'stock_counts', 'stock_locations',
    'subcontract_change_orders', 'subcontract_payment_controls',
    'subcontract_sov_lines', 'subcontracts', 'subscription_amendments',
    'subscription_components', 'subscription_events', 'subscription_lifecycles',
    'subscription_period_invoices', 'subscription_plan_version_components',
    'subscription_plan_versions', 'subscription_plans', 'subscriptions',
    'subsidiary_ownership_interests', 'tax_codes', 'tax_country_pack_installations',
    'tax_depreciation_pools', 'tax_filings', 'tax_first_year_rules',
    'tax_groups', 'tax_jurisdictions', 'tax_locale_pack_meta',
    'tax_pool_classes', 'tax_pool_periods', 'tax_provision_runs', 'tax_rates',
    'tax_regimes', 'tax_registrations', 'tax_report_lines', 'tax_return_forms',
    'temporary_differences', 'time_entries', 'time_types', 'trades',
    'transfer_order_lines', 'transfer_orders', 'vendor_pay_application_lines',
    'vendor_pay_applications', 'vendor_retainage_releases', 'wip_holds',
    'wip_prebill_events', 'wip_prebill_lines', 'wip_prebills', 'worker_comp_groups',
    'employee_pay_components',
    'pay_components', 'pay_derived_rules', 'pay_run_adjustments', 'pay_runs',
    'pay_schedules', 'pay_stub_lines', 'pay_stubs',
    'payroll_filing_accounts', 'payroll_holidays',
    'payroll_opening_balance_components', 'payroll_opening_balances',
    'union_agreements', 'union_classifications',
    'union_fringes'
  ];
begin
  -- Public base tables are never query-console surfaces. Revoke both current
  -- and future access before rebuilding the reviewed view catalog.
  revoke all privileges on all tables in schema public from openbooks_read;
  alter default privileges in schema public revoke select on tables from openbooks_read;

  drop schema if exists openbooks_query cascade;
  create schema openbooks_query;
  revoke all on schema openbooks_query from public;
  grant usage on schema openbooks_query to openbooks_read;

  foreach relation_name in array safe_relations loop
    if to_regclass(format('public.%I', relation_name)) is null then
      raise exception 'governed query relation is missing: %', relation_name;
    end if;
    -- SELECT * is expanded and frozen when the view is created, so a column
    -- added later is not queryable until this function runs again.
    --
    -- That is a WEAK guarantee and must not be mistaken for review: this
    -- function is a single call with no approval step, and the baseline itself
    -- ends by calling it. A relation that can ever hold a secret therefore does
    -- NOT belong in this array — give it an explicit curated column list below,
    -- where adding a sensitive column is a visible, reviewable diff.
    select exists (
      select 1 from information_schema.columns
       where table_schema = 'public' and table_name = relation_name and column_name = 'org_id'
    ) into has_org_id;
    if has_org_id then
      execute format(
        'create view openbooks_query.%1$I with (security_barrier=true) as '
        'select * from public.%1$I '
        'where org_id = public.openbooks_query_org_id()',
        relation_name
      );
    elsif relation_name = any(global_relations) then
      execute format(
        'create view openbooks_query.%1$I with (security_barrier=true) as select * from public.%1$I',
        relation_name
      );
    else
      raise exception
        'governed query relation % has no org_id and is not an explicitly reviewed global relation',
        relation_name;
    end if;
    execute format('grant select on openbooks_query.%I to openbooks_read', relation_name);
  end loop;

  -- Party dimensions are reportable, but full tax identifiers, sealed bank
  -- details and arbitrary source-system custom payloads are not.
  create view openbooks_query.parties with (security_barrier=true) as
    select id, org_id, kind, display_name, legal_name, short_code, email, phone,
           website, subsidiary_id, is_active, invoicing_preference,
           invoicing_profile, created_at, created_by, updated_at, updated_by
      from public.parties
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.customer_roles with (security_barrier=true) as
    select id, org_id, party_id, ar_account_id, payment_terms_id, credit_limit,
           currency, sales_rep_id, tax_code_id, is_on_hold, hold_reason, held_at,
           held_by, is_active, created_at, created_by, updated_at, updated_by
      from public.customer_roles
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.vendor_roles with (security_barrier=true) as
    select id, org_id, party_id, ap_account_id, payment_terms_id,
           default_expense_account_id, payment_method, eft_notification_email,
           currency, tax_code_id, is_t4a, compliance_class_id,
           information_return_form, information_return_box, tax_classification,
           tin_last4, tin_type, backup_withholding, is_on_hold, hold_reason,
           held_at, held_by, is_active, created_at, created_by, updated_at, updated_by
      from public.vendor_roles
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.party_bank_accounts with (security_barrier=true) as
    select id, org_id, party_id, bank_name, country, currency, account_last_four,
           approved_at, approved_by, approval_status, submitted_by, submitted_at,
           retired_at, retired_by, retirement_reason, is_active,
           created_at, created_by, updated_at, updated_by
      from public.party_bank_accounts
     where org_id = public.openbooks_query_org_id();
  create view openbooks_query.subsidiaries with (security_barrier=true) as
    select id, org_id, parent_id, name, legal_name, base_currency, country,
           is_elimination, is_active, created_at, created_by, updated_at, updated_by
      from public.subsidiaries
     where org_id = public.openbooks_query_org_id();
  -- Payroll profiles are reportable, but the sealed national identifier is not:
  -- sin_encrypted is envelope-encrypted SIN/SSN ciphertext and never leaves the
  -- payroll engine. sin_last3 is the identify-without-reveal substitute.
  create view openbooks_query.employee_payroll_profiles with (security_barrier=true) as
    select id, org_id, employee_party_id, pay_schedule_id, province,
           pay_basis, federal_claim_code, federal_claim_amount,
           provincial_claim_code, provincial_claim_amount,
           additional_tax_per_period, prescribed_zone_deduction,
           authorized_annual_deductions, authorized_federal_credits,
           authorized_provincial_credits, cpp_exempt, ei_exempt,
           tax_exempt, vacation_percent, vacation_method, is_active,
           created_at, created_by, updated_at, updated_by,
           union_agreement_id, union_classification_id, country,
           filing_status, multiple_jobs, dependent_credits,
           other_income_annual, deductions_annual, w4_pre_2020,
           w4_allowances, fica_exempt, futa_exempt, sin_last3,
           filing_account_id, stub_delivery, payment_method,
           labour_jurisdiction
      from public.employee_payroll_profiles
     where org_id = public.openbooks_query_org_id();
  -- Employment records are reportable; date of birth is not. It exists for ROE
  -- demographics and the stub-password policy, and the schema comment on
  -- employee_roles.birth_date already states it stays out of these views.
  create view openbooks_query.employee_roles with (security_barrier=true) as
    select id, org_id, party_id, employee_number, department_id,
           supervisor_id, trade_id, worker_comp_group_id, hired_on,
           terminated_on, has_benefits, vacation_days_per_year,
           billable_utilization_target, expense_account_id,
           external_payroll_id, is_active, custom, created_at, created_by,
           updated_at, updated_by, job_title
      from public.employee_roles
     where org_id = public.openbooks_query_org_id();
  -- Membership rows inherit tenancy through their owning tax group. They
  -- deliberately cannot use the generic catalog path because the base table
  -- has no org_id of its own.
  create view openbooks_query.tax_group_members with (security_barrier=true) as
    select member.id, member.tax_group_id, member.tax_code_id, member.sequence
      from public.tax_group_members member
      join public.tax_groups tax_group on tax_group.id = member.tax_group_id
     where tax_group.org_id = public.openbooks_query_org_id();

  foreach relation_name in array array[
    'parties', 'customer_roles', 'vendor_roles', 'party_bank_accounts',
    'subsidiaries', 'employee_payroll_profiles', 'employee_roles',
    'tax_group_members'
  ] loop
    execute format('grant select on openbooks_query.%I to openbooks_read', relation_name);
  end loop;
end;
$_$;


--
-- Name: openbooks_sandbox_wipe_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_sandbox_wipe_allowed(p_org_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(current_setting('openbooks.sandbox_wipe', true), 'off') = 'on'
     and exists (
       select 1 from orgs where id = p_org_id and env_kind = 'sandbox'
     )
$$;


--
-- Name: openbooks_valid_form_sections(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_valid_form_sections(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN jsonb_typeof(value) IS DISTINCT FROM 'array' THEN false
    ELSE NOT EXISTS (
      SELECT 1
        FROM jsonb_array_elements(value) section
       WHERE jsonb_typeof(section) IS DISTINCT FROM 'object'
          OR jsonb_typeof(section->'fields') IS DISTINCT FROM 'array'
    )
  END
$$;


--
-- Name: openbooks_valid_report_attachments(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_valid_report_attachments(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN jsonb_typeof(value) IS DISTINCT FROM 'array' THEN false
    ELSE NOT EXISTS (
      SELECT 1
        FROM jsonb_array_elements(value) attachment
       WHERE jsonb_typeof(attachment) IS DISTINCT FROM 'object'
          OR jsonb_typeof(attachment->'slug') IS DISTINCT FROM 'string'
          OR length(btrim(attachment->>'slug')) = 0
    )
  END
$$;


--
-- Name: openbooks_validate_depreciation_line_input(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.openbooks_validate_depreciation_line_input() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare
  input_row depreciation_inputs%rowtype;
  schedule_method text;
begin
  if new.source in ('formula', 'imported') then return new; end if;
  select * into input_row from depreciation_inputs where id = new.input_id;
  if not found
     or input_row.voided_at is not null
     or input_row.org_id <> new.org_id
     or input_row.schedule_id <> new.schedule_id
     or input_row.period_id <> new.period_id then
    raise exception 'depreciation line input evidence does not match its schedule and period';
  end if;
  select method into schedule_method from depreciation_schedules where id = new.schedule_id;
  if (new.source = 'manual' and (input_row.kind <> 'manual' or schedule_method <> 'manual'))
     or (new.source = 'production_usage' and (input_row.kind <> 'production_usage' or schedule_method <> 'units_of_production')) then
    raise exception 'depreciation line source does not match its method evidence';
  end if;
  return new;
end;
$$;


--
-- Name: overhead_rates_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.overhead_rates_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (
    select 1
      from overhead_rates r
     where r.id <> new.id
       and r.org_id = new.org_id
       and r.department_id is not distinct from new.department_id
       and coalesce(lower(r.category), '') = coalesce(lower(new.category), '')
       and r.method = new.method
       and r.rate_kind = new.rate_kind
       and effective_date_ranges_overlap(r.effective_from, r.effective_to, new.effective_from, new.effective_to)
  ) then
    raise exception 'overhead rates overlap for the same department/category/method/rate kind scope' using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: ownership_interest_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ownership_interest_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare actual_parent uuid; bad_account boolean;
begin
  select parent_id into actual_parent from subsidiaries where id=new.subsidiary_id and org_id=new.org_id and is_active and not is_elimination;
  if actual_parent is distinct from new.parent_subsidiary_id or not exists (select 1 from subsidiaries where id=new.parent_subsidiary_id and org_id=new.org_id and is_active and not is_elimination) then raise exception 'ownership interest must follow the active tenant consolidation hierarchy'; end if;
  if exists (
    select 1 from subsidiary_ownership_interests x
     where x.org_id = new.org_id
       and x.id <> new.id
       and x.is_active and new.is_active
       and x.subsidiary_id = new.subsidiary_id
       and effective_date_ranges_overlap(x.effective_from, x.effective_to, new.effective_from, new.effective_to)
  ) then raise exception 'ownership effective dates overlap for the subsidiary'; end if;
  select exists (select 1 from unnest(array_remove(array[new.investment_account_id,new.equity_income_account_id,new.distribution_account_id,new.distribution_income_account_id,new.nci_equity_account_id,new.nci_income_account_id,new.goodwill_account_id,new.fair_value_adjustment_account_id],null)) wanted(id) where not exists (select 1 from accounts a where a.id=wanted.id and a.org_id=new.org_id and a.is_active and not a.is_summary)) into bad_account;
  if bad_account then raise exception 'ownership accounts must be active postable accounts in the tenant'; end if;
  if new.method='full' and new.ownership_percent<100 and (new.nci_equity_account_id is null or new.nci_income_account_id is null) then raise exception 'full consolidation below 100 percent requires NCI equity and income accounts'; end if;
  if new.method='full' and (new.goodwill_account_id is null or new.fair_value_adjustment_account_id is null) then raise exception 'full consolidation requires goodwill and fair-value adjustment accounts'; end if;
  if new.distribution_account_id is not null and new.distribution_income_account_id is null then raise exception 'distribution income account is required when a distribution account is configured'; end if;
  if tg_op='UPDATE' and exists(select 1 from ownership_consolidation_entries where interest_id=old.id) and row(new.org_id,new.parent_subsidiary_id,new.subsidiary_id,new.effective_from,new.effective_to,new.ownership_percent,new.method,new.acquisition_date,new.acquisition_cost,new.fair_value_net_assets,new.acquisition_rate,new.nci_measurement,new.nci_fair_value,new.investment_account_id,new.equity_income_account_id,new.distribution_account_id,new.distribution_income_account_id,new.nci_equity_account_id,new.nci_income_account_id,new.goodwill_account_id,new.fair_value_adjustment_account_id,new.is_active) is distinct from row(old.org_id,old.parent_subsidiary_id,old.subsidiary_id,old.effective_from,old.effective_to,old.ownership_percent,old.method,old.acquisition_date,old.acquisition_cost,old.fair_value_net_assets,old.acquisition_rate,old.nci_measurement,old.nci_fair_value,old.investment_account_id,old.equity_income_account_id,old.distribution_account_id,old.distribution_income_account_id,old.nci_equity_account_id,old.nci_income_account_id,old.goodwill_account_id,old.fair_value_adjustment_account_id,old.is_active) then raise exception 'used ownership policy is immutable; close it and create a new effective-dated policy'; end if;
  return new;
end $$;


--
-- Name: party_subsidiary_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.party_subsidiary_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from parties p where p.id = new.party_id and p.org_id = new.org_id) then
    raise exception 'party belongs to another organization' using errcode = '23514';
  end if;
  if not exists (
    select 1 from subsidiaries s
     where s.id = new.subsidiary_id and s.org_id = new.org_id and not s.is_elimination
  ) then
    raise exception 'party subsidiary is invalid' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: payment_event_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_event_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and openbooks_sandbox_wipe_allowed(old.org_id) then
    return old;
  end if;
  raise exception 'payment events are append-only';
end $$;


--
-- Name: payment_file_artifact_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_file_artifact_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.payment_run_id is distinct from old.payment_run_id
     or new.payment_bank_profile_id is distinct from old.payment_bank_profile_id
     or new.payment_format_id is distinct from old.payment_format_id
     or new.parent_payment_file_id is distinct from old.parent_payment_file_id
     or new.sequence_number is distinct from old.sequence_number
     or new.filename is distinct from old.filename
     or new.content_type is distinct from old.content_type
     or new.content_hash is distinct from old.content_hash
     or new.file_id is distinct from old.file_id
     or new.file_version_id is distinct from old.file_version_id
     or new.payment_count is distinct from old.payment_count
     or new.total_amount is distinct from old.total_amount
     or new.currency is distinct from old.currency
     or new.generated_at is distinct from old.generated_at
     or new.generated_by is distinct from old.generated_by then
    raise exception 'generated payment file artifacts are immutable; reprocess into a new file';
  end if;
  return new;
end $$;


--
-- Name: payment_run_item_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_run_item_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_status text;
begin
  select status into v_status from payment_runs where id = coalesce(new.payment_run_id, old.payment_run_id);
  if tg_op = 'DELETE' and v_status not in ('draft', 'pending_approval')
     and not openbooks_sandbox_wipe_allowed(old.org_id) then
    raise exception 'payment run items are immutable once the run is approved';
  end if;
  if tg_op = 'UPDATE' and v_status not in ('draft', 'pending_approval') and (
     new.payment_run_id is distinct from old.payment_run_id
     or new.payment_instruction_id is distinct from old.payment_instruction_id
     or new.source_document_id is distinct from old.source_document_id
     or new.source_open_line_id is distinct from old.source_open_line_id
     or new.kind is distinct from old.kind
     or new.gross_amount is distinct from old.gross_amount
     or new.discount_amount is distinct from old.discount_amount
     or new.credit_amount is distinct from old.credit_amount
     or new.payment_amount is distinct from old.payment_amount
     or new.currency is distinct from old.currency
     or new.fx_rate is distinct from old.fx_rate) then
    raise exception 'payment run item composition is immutable once the run is approved';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: period_module_blocks_write(uuid, uuid, uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.period_module_blocks_write(p_org uuid, p_period uuid, p_book uuid, p_subsidiary uuid, p_module text, p_allow_imported boolean) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (select case
       when p_allow_imported and reason = 'close.importedPeriodLockReason' then false
       when state = 'closed' then true
       when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
       else false
     end
       from period_locks
      where org_id = p_org and period_id = p_period and book_id = p_book
        and subsidiary_id = p_subsidiary and module = p_module),
    (select case
       when p_allow_imported and reason = 'close.importedPeriodLockReason' then false
       when state = 'closed' then true
       when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
       else false
     end
       from period_locks
      where org_id = p_org and period_id = p_period and book_id = p_book
        and subsidiary_id is null and module = p_module),
    false
  )
$$;


--
-- Name: period_module_is_closed(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.period_module_is_closed(p_org uuid, p_period uuid, p_book uuid, p_subsidiary uuid, p_module text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select coalesce(
    (select case
       when state = 'closed' then true
       when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
       else false
     end
       from period_locks
      where org_id = p_org and period_id = p_period and book_id = p_book
        and subsidiary_id = p_subsidiary and module = p_module),
    (select case
       when state = 'closed' then true
       when state = 'open' and reopen_expires_at is not null and reopen_expires_at <= now() then true
       else false
     end
       from period_locks
      where org_id = p_org and period_id = p_period and book_id = p_book
        and subsidiary_id is null and module = p_module),
    false
  )
$$;


--
-- Name: posted_document_financial_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.posted_document_financial_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(current_setting('openbooks.sandbox_wipe', true), 'off') = 'on' then
    return new;
  end if;
  if openbooks_sandbox_wipe_allowed(old.org_id) then
    return new;
  end if;
  if coalesce(current_setting('openbooks.amend', true), 'off') <> 'on' then
    raise exception 'document % is % — its financial identity (totals, dates, currency, party, kind, number) is immutable outside the governed amend path', old.id, old.status;
  end if;
  return new;
end $$;


--
-- Name: project_financial_adjustment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_financial_adjustment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF tg_op = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(old.org_id)
  THEN
    RETURN old;
  END IF;
  IF tg_op IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION
      'project financial adjustments are append-only; post a reversing adjustment';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM projects p
     WHERE p.id = new.project_id
       AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial adjustment must belong to the project organization';
  END IF;
  IF new.reverses_adjustment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_financial_adjustments original
     WHERE original.id = new.reverses_adjustment_id
       AND original.org_id = new.org_id
       AND original.project_id = new.project_id
       AND original.measure = new.measure
       AND original.amount = -new.amount
  ) THEN
    RAISE EXCEPTION
      'a reversing project financial adjustment must exactly offset the same project and measure';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: project_financial_profile_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_financial_profile_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  publish_mode boolean :=
    coalesce(current_setting('openbooks.publish_project_profile', true), 'off') = 'on';
  correction_mode boolean :=
    coalesce(current_setting('openbooks.correct_project_profile', true), 'off') = 'on';
  correction_reason text :=
    coalesce(current_setting('openbooks.project_profile_correction_reason', true), '');
BEGIN
  IF tg_op <> 'DELETE' AND NOT EXISTS (
    SELECT 1
      FROM project_types pt
     WHERE pt.id = new.project_type_id
       AND pt.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project financial profile version must belong to the project type organization';
  END IF;

  IF tg_op = 'DELETE' THEN
    RAISE EXCEPTION 'published project financial profile versions are immutable';
  END IF;

  IF tg_op = 'UPDATE' THEN
    IF correction_mode THEN
      IF length(btrim(correction_reason)) < 8
         OR (to_jsonb(new) - 'financial_profile' - 'updated_at' - 'updated_by')
            IS DISTINCT FROM
            (to_jsonb(old) - 'financial_profile' - 'updated_at' - 'updated_by')
      THEN
        RAISE EXCEPTION
          'controlled project financial profile correction may change only policy JSON and requires a reason';
      END IF;
    ELSIF NOT publish_mode
       OR (to_jsonb(new) - 'effective_to' - 'updated_at' - 'updated_by')
          IS DISTINCT FROM
          (to_jsonb(old) - 'effective_to' - 'updated_at' - 'updated_by')
    THEN
      RAISE EXCEPTION 'published project financial profile versions are immutable';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
      FROM project_financial_profile_versions v
     WHERE v.org_id = new.org_id
       AND v.project_type_id = new.project_type_id
       AND v.id <> new.id
       AND daterange(v.effective_from, v.effective_to, '[]')
           && daterange(new.effective_from, new.effective_to, '[]')
  ) THEN
    RAISE EXCEPTION 'project financial profile effective ranges cannot overlap';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: project_overhead_adjustment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_overhead_adjustment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF tg_op = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(old.org_id)
  THEN
    RETURN old;
  END IF;
  IF tg_op IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION
      'project overhead adjustments are append-only; post a reversing adjustment';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM projects p
     WHERE p.id = new.project_id
       AND p.org_id = new.org_id
  ) THEN
    RAISE EXCEPTION
      'project overhead adjustment must belong to the project organization';
  END IF;
  IF new.reverses_adjustment_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
      FROM project_overhead_adjustments original
     WHERE original.id = new.reverses_adjustment_id
       AND original.org_id = new.org_id
       AND original.project_id = new.project_id
       AND original.amount = -new.amount
  ) THEN
    RAISE EXCEPTION
      'a reversing overhead adjustment must exactly offset the same project';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: property_financial_evidence_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.property_financial_evidence_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF openbooks_sandbox_wipe_allowed(CASE WHEN TG_OP='DELETE' THEN OLD.org_id ELSE NEW.org_id END) THEN
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
  END IF;
  RAISE EXCEPTION 'property financial evidence is append-only';
END $$;


--
-- Name: protect_application_idempotency_key(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_application_idempotency_key() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.expires_at <= now()
       OR current_setting('app.bypass_rls', true) = 'on' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'unexpired application idempotency evidence cannot be deleted';
  END IF;

  IF OLD.completed_at IS NULL
     AND NEW.completed_at IS NOT NULL
     AND NEW.response IS NOT NULL
     AND NEW.org_id = OLD.org_id
     AND NEW.actor_id = OLD.actor_id
     AND NEW.source = OLD.source
     AND NEW.operation = OLD.operation
     AND NEW.idempotency_key = OLD.idempotency_key
     AND NEW.request_hash = OLD.request_hash
     AND NEW.created_at = OLD.created_at
     AND NEW.expires_at = OLD.expires_at THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'application idempotency evidence is immutable after creation';
END;
$$;


--
-- Name: protect_country_tax_pack_installation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_country_tax_pack_installation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND current_setting('openbooks.sandbox_wipe', true) = 'on'
     AND EXISTS (
       SELECT 1
         FROM orgs
        WHERE id = OLD.org_id
          AND env_kind = 'sandbox'
     ) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'country tax pack installation evidence is immutable';
  END IF;
  IF OLD.status = 'active'
     AND NEW.status = 'superseded'
     AND NEW.org_id = OLD.org_id
     AND NEW.pack_code = OLD.pack_code
     AND NEW.country = OLD.country
     AND NEW.version = OLD.version
     AND NEW.content_hash = OLD.content_hash
     AND NEW.manifest = OLD.manifest
     AND NEW.installed_at = OLD.installed_at
     AND NEW.installed_by IS NOT DISTINCT FROM OLD.installed_by
     AND NEW.superseded_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'country tax pack installation may only transition from active to superseded';
END;
$$;


--
-- Name: protect_tax_provision_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tax_provision_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
    RETURN OLD;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION
        'finalized income-tax provision runs are append-only (run %, status %)',
        OLD.id, OLD.status;
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status IN ('discarded', 'superseded') THEN
    RAISE EXCEPTION
      'finalized income-tax provision runs are immutable (run %, status %)',
      OLD.id, OLD.status;
  END IF;

  IF OLD.status = 'posted' AND NEW.status <> 'superseded' THEN
    RAISE EXCEPTION
      'posted income-tax provision runs may only transition to superseded (run %)',
      OLD.id;
  END IF;

  IF OLD.status = 'posted' AND (
    NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.fiscal_year IS DISTINCT FROM OLD.fiscal_year
    OR NEW.period_from IS DISTINCT FROM OLD.period_from
    OR NEW.period_to IS DISTINCT FROM OLD.period_to
    OR NEW.version IS DISTINCT FROM OLD.version
    OR NEW.snapshot_hash IS DISTINCT FROM OLD.snapshot_hash
    OR NEW.payload IS DISTINCT FROM OLD.payload
    OR NEW.journal_entry_id IS DISTINCT FROM OLD.journal_entry_id
    OR NEW.posted_at IS DISTINCT FROM OLD.posted_at
    OR NEW.posted_by IS DISTINCT FROM OLD.posted_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
  ) THEN
    RAISE EXCEPTION
      'posted income-tax provision evidence is immutable (run %)',
      OLD.id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: protect_temporary_difference_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_temporary_difference_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_org_id uuid;
  target_run_id uuid;
  target_status text;
BEGIN
  target_org_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.org_id ELSE NEW.org_id END;
  IF TG_OP = 'DELETE'
     AND openbooks_sandbox_wipe_allowed(target_org_id) THEN
    RETURN OLD;
  END IF;

  target_run_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.run_id ELSE NEW.run_id END;
  SELECT status
    INTO target_status
    FROM tax_provision_runs
   WHERE id = target_run_id
     AND org_id = target_org_id;

  IF target_status IS NULL THEN
    RAISE EXCEPTION 'temporary difference must reference a tenant-owned provision run';
  END IF;
  IF target_status <> 'draft' THEN
    RAISE EXCEPTION
      'temporary differences are immutable after provision finalization (run %, status %)',
      target_run_id, target_status;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: rate_adjustment_target_version_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_adjustment_target_version_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  SELECT version.status, adjustment.org_id
    INTO v_status, v_org_id
    FROM labor_rate_adjustments adjustment
    JOIN item_rate_versions version
      ON version.id = adjustment.version_id
     AND version.org_id = adjustment.org_id
   WHERE adjustment.id = coalesce(NEW.adjustment_id, OLD.adjustment_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'adjustment target must reference a tenant-owned rate version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'targets of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: rate_book_currency_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_book_currency_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF openbooks_sandbox_wipe_allowed(OLD.org_id) THEN RETURN OLD; END IF;
    IF EXISTS (
      SELECT 1 FROM item_rate_versions version
       WHERE version.rate_book_id = OLD.id
    ) THEN
      RAISE EXCEPTION 'a rate book with version history cannot be deleted';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.org_id IS DISTINCT FROM OLD.org_id THEN
    RAISE EXCEPTION 'rate book organization is immutable';
  END IF;
  IF NEW.currency IS DISTINCT FROM OLD.currency
     AND EXISTS (
       SELECT 1 FROM item_rate_versions version
        WHERE version.rate_book_id = OLD.id
     ) THEN
    RAISE EXCEPTION 'rate book currency cannot change after version history exists';
  END IF;
  RETURN NEW;
END
$$;


--
-- Name: rate_version_child_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_child_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_status text;
  v_org_id uuid;
BEGIN
  SELECT status, org_id
    INTO v_status, v_org_id
    FROM item_rate_versions
   WHERE id = coalesce(NEW.version_id, OLD.version_id);
  IF v_status IS NULL
     OR v_org_id IS DISTINCT FROM coalesce(NEW.org_id, OLD.org_id) THEN
    RAISE EXCEPTION 'rate-version child must reference a tenant-owned version'
      USING ERRCODE = '23514';
  END IF;
  IF v_status <> 'draft' THEN
    IF TG_OP = 'DELETE'
       AND openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'children of an activated or retired rate version are immutable';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: rate_version_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_version_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'draft'
       OR openbooks_sandbox_wipe_allowed(OLD.org_id) THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'activated and retired rate versions cannot be deleted';
  END IF;
  IF OLD.status = 'draft' THEN RETURN NEW; END IF;

  IF OLD.status = 'active' AND NEW.status = 'active'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom
     AND NEW.effective_to IS NOT NULL
     AND NEW.effective_to >= OLD.effective_from
     AND (OLD.effective_to IS NULL OR NEW.effective_to <= OLD.effective_to) THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'active' AND NEW.status = 'retired'
     AND NEW.org_id = OLD.org_id
     AND NEW.rate_book_id = OLD.rate_book_id
     AND NEW.effective_from = OLD.effective_from
     AND NEW.effective_to IS NOT DISTINCT FROM OLD.effective_to
     AND NEW.custom IS NOT DISTINCT FROM OLD.custom THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'activated and retired rate versions are immutable';
END
$$;


--
-- Name: recompute_document_open_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_document_open_balance(p_doc uuid) RETURNS void
    LANGUAGE sql
    AS $$
  UPDATE documents d SET open_balance = CASE
    WHEN d.status = 'voided' THEN NULL
    ELSE (
      SELECT CASE WHEN count(jl.id) = 0 THEN NULL
             ELSE sum(abs(jl.amount)) - coalesce(sum(ap.applied), 0) END
        FROM journal_lines jl
        LEFT JOIN LATERAL (
          SELECT sum(a.amount) AS applied
            FROM applications a
           WHERE (a.to_line_id = jl.id OR a.from_line_id = jl.id)
             AND a.unapplied_at IS NULL
        ) ap ON true
       WHERE jl.entry_id = d.posted_entry_id AND jl.is_open_item
    )
    END
  WHERE d.id = p_doc;
$$;


--
-- Name: row_extra_dims_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.row_extra_dims_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_subsidiary uuid;
begin
  v_subsidiary := new.subsidiary_id;
  if tg_table_name = 'document_lines' and v_subsidiary is null then
    select subsidiary_id into v_subsidiary from documents where id = new.document_id;
  end if;
  if v_subsidiary is null then
    select id into v_subsidiary from subsidiaries where org_id = new.org_id and parent_id is null;
  end if;
  perform validate_extra_dims(new.org_id, new.extra_dims, v_subsidiary);
  return new;
end $$;


--
-- Name: seed_builtin_segments(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_builtin_segments(p_org_id uuid) RETURNS void
    LANGUAGE sql
    AS $$
  insert into segment_definitions
    (org_id, key, name, plural_name, source_kind, storage_column,
     is_hierarchical, show_on_header, show_on_lines, show_in_reports,
     allow_account_requirement, sort_order)
  values
    (p_org_id, 'subsidiary', 'Subsidiary', 'Subsidiaries', 'builtin', 'subsidiary_id', true, true, true, true, false, 10),
    (p_org_id, 'department', 'Department', 'Departments', 'builtin', 'department_id', true, true, true, true, true, 20),
    (p_org_id, 'project', 'Project', 'Projects', 'builtin', 'project_id', true, true, true, true, true, 30),
    (p_org_id, 'location', 'Location', 'Locations', 'builtin', 'location_id', true, true, true, true, true, 40),
    (p_org_id, 'class', 'Class', 'Classes', 'builtin', 'class_id', true, true, true, true, true, 50)
  on conflict (org_id, key) do nothing
$$;


--
-- Name: seed_builtin_segments_on_org_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_builtin_segments_on_org_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  -- Sandbox tenants clone the production segment graph with deterministically
  -- rebased identities; pre-seeding would create duplicate logical keys.
  if new.env_kind = 'sandbox' then return new; end if;
  perform seed_builtin_segments(new.id);
  return new;
end $$;


--
-- Name: segment_definition_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.segment_definition_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' and old.source_kind = 'builtin'
     and not openbooks_sandbox_wipe_allowed(old.org_id) then
    raise exception 'built-in segment definitions cannot be deleted' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and old.source_kind = 'builtin' and
     (new.key <> old.key or new.source_kind <> old.source_kind or new.storage_column is distinct from old.storage_column) then
    raise exception 'built-in segment identity cannot be changed' using errcode = '23514';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;


--
-- Name: segment_value_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.segment_value_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_hierarchical boolean;
begin
  select is_hierarchical into v_hierarchical
    from segment_definitions
   where id = new.segment_id and org_id = new.org_id and source_kind = 'custom';
  if v_hierarchical is null then
    raise exception 'segment value must belong to a custom segment in this organization' using errcode = '23514';
  end if;
  if new.subsidiary_id is not null and not exists (
    select 1 from subsidiaries where id = new.subsidiary_id and org_id = new.org_id
  ) then
    raise exception 'segment value subsidiary belongs to another organization' using errcode = '23514';
  end if;
  if new.parent_id is not null then
    if not v_hierarchical then
      raise exception 'this segment is not hierarchical' using errcode = '23514';
    end if;
    if not exists (select 1 from segment_values p where p.id = new.parent_id
      and p.org_id = new.org_id and p.segment_id = new.segment_id) then
      raise exception 'segment value parent is invalid' using errcode = '23514';
    end if;
    if new.parent_id = new.id or exists (
      with recursive descendants as (
        select id from segment_values where parent_id = new.id
        union all
        select v.id from segment_values v join descendants d on v.parent_id = d.id
      ) select 1 from descendants where id = new.parent_id
    ) then
      raise exception 'segment value hierarchy contains a cycle' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: subscription_amendment_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_amendment_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('app.sandbox_wipe',true)='on' THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END IF;
  IF OLD.status='applied' THEN RAISE EXCEPTION 'applied subscription amendments are immutable'; END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: subscription_period_invoice_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_period_invoice_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('app.sandbox_wipe',true)='on' THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END IF;
  RAISE EXCEPTION 'subscription period invoice lineage is immutable';
END $$;


--
-- Name: subscription_plan_version_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_plan_version_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('app.sandbox_wipe',true)='on' THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END IF;
  IF OLD.status IN ('published','superseded') THEN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'published subscription plan versions are immutable'; END IF;
    IF ROW(OLD.plan_id,OLD.effective_from,OLD.name,OLD.description,OLD.currency_code,OLD.interval,OLD.interval_count,OLD.billing_timing,OLD.published_at,OLD.published_by)
      IS DISTINCT FROM ROW(NEW.plan_id,NEW.effective_from,NEW.name,NEW.description,NEW.currency_code,NEW.interval,NEW.interval_count,NEW.billing_timing,NEW.published_at,NEW.published_by)
    THEN RAISE EXCEPTION 'published subscription plan commercial terms are immutable'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: subscription_version_component_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subscription_version_component_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_version uuid; parent_status text;
BEGIN
  IF current_setting('app.sandbox_wipe',true)='on' THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END IF;
  parent_version := CASE WHEN TG_OP='DELETE' THEN OLD.version_id ELSE NEW.version_id END;
  SELECT status INTO parent_status FROM subscription_plan_versions WHERE id=parent_version;
  IF parent_status IN ('published','superseded') THEN RAISE EXCEPTION 'components of published subscription plan versions are immutable'; END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;


--
-- Name: subsidiary_ref_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subsidiary_ref_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.subsidiary_id is not null and not exists (
    select 1 from subsidiaries s where s.id = new.subsidiary_id and s.org_id = new.org_id
  ) then
    raise exception 'subsidiary belongs to another organization' using errcode = '23514';
  end if;
  return new;
end $$;


--
-- Name: subsidiary_tree_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subsidiary_tree_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.parent_id is null
       and exists (select 1 from orgs where id = old.org_id)
       and not openbooks_sandbox_wipe_allowed(old.org_id) then
      raise exception 'the root subsidiary cannot be deleted' using errcode = '23514';
    end if;
    return old;
  end if;
  if tg_op = 'UPDATE' and old.parent_id is null and new.parent_id is not null then
    raise exception 'the root subsidiary cannot be moved' using errcode = '23514';
  end if;
  if new.parent_id is null and not new.is_active then
    raise exception 'the root subsidiary cannot be inactive' using errcode = '23514';
  end if;
  if new.parent_id is not null then
    if not exists (select 1 from subsidiaries p where p.id = new.parent_id and p.org_id = new.org_id) then
      raise exception 'subsidiary parent belongs to another organization' using errcode = '23514';
    end if;
    if new.parent_id = new.id or exists (
      with recursive descendants as (
        select id from subsidiaries where parent_id = new.id
        union all
        select s.id from subsidiaries s join descendants d on s.parent_id = d.id
      ) select 1 from descendants where id = new.parent_id
    ) then
      raise exception 'subsidiary hierarchy contains a cycle' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


--
-- Name: tax_filing_immutable_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_filing_immutable_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if tg_op = 'DELETE' then
    if openbooks_sandbox_wipe_allowed(old.org_id) then return old; end if;
    raise exception 'tax filing snapshots cannot be deleted';
  end if;
  if old.status = 'prepared' and new.status = 'filed'
     and (to_jsonb(new) - 'status' - 'filing_reference' - 'filed_at' - 'updated_at' - 'updated_by')
       = (to_jsonb(old) - 'status' - 'filing_reference' - 'filed_at' - 'updated_at' - 'updated_by')
  then
    return new;
  end if;
  raise exception 'tax filing snapshots are immutable';
end $$;


--
-- Name: tax_group_member_validate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_group_member_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare group_org uuid; code_org uuid;
begin
  if new.sequence <= 0 then raise exception 'tax group member sequence must be positive'; end if;
  select org_id into group_org from tax_groups where id = new.tax_group_id;
  select org_id into code_org from tax_codes where id = new.tax_code_id;
  if group_org is null or code_org is null or group_org <> code_org then
    raise exception 'tax group and tax code must belong to the same organization';
  end if;
  return new;
end $$;


--
-- Name: tax_rates_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_rates_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if exists (
    select 1
      from tax_rates r
     where r.id <> new.id
       and r.org_id = new.org_id
       and r.tax_code_id = new.tax_code_id
       and effective_date_ranges_overlap(r.effective_from, r.effective_to, new.effective_from, new.effective_to)
  ) then
    raise exception 'tax rates overlap for tax code %', new.tax_code_id using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: tax_registrations_no_overlap_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tax_registrations_no_overlap_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not new.is_active then return new; end if;
  if exists (
    select 1
      from tax_registrations r
     where r.id <> new.id
       and r.org_id = new.org_id
       and r.is_active
       and r.jurisdiction_id = new.jurisdiction_id
       and coalesce(r.return_form_code, '') = coalesce(new.return_form_code, '')
       and effective_date_ranges_overlap(coalesce(r.effective_from, '-infinity'::date), r.effective_to, coalesce(new.effective_from, '-infinity'::date), new.effective_to)
  ) then
    raise exception 'tax registrations overlap for jurisdiction % and return form %', new.jurisdiction_id, coalesce(new.return_form_code, '') using errcode = '23P01';
  end if;
  return new;
end $$;


--
-- Name: trg_application_open_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_application_open_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
declare v_doc uuid;
begin
  if openbooks_sandbox_wipe_allowed(
       case when tg_op = 'DELETE' then old.org_id else new.org_id end
     ) then
    return null;
  end if;
  for v_doc in
    select distinct d.id
      from documents d
      join journal_lines jl on jl.entry_id = d.posted_entry_id
     where jl.is_open_item
       and jl.id in (coalesce(new.to_line_id, old.to_line_id),
                     coalesce(new.from_line_id, old.from_line_id))
  loop
    perform recompute_document_open_balance(v_doc);
  end loop;
  return null;
end $$;


--
-- Name: trg_document_open_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_document_open_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM recompute_document_open_balance(NEW.id);
  RETURN NULL;
END $$;


--
-- Name: uuid_generate_v7(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.uuid_generate_v7() RETURNS uuid
    LANGUAGE sql PARALLEL SAFE
    AS $$
      select encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid())
        placing substring(int8send((extract(epoch from clock_timestamp()) * 1000)::bigint) from 3)
        from 1 for 6), 52, 1), 53, 1), 'hex')::uuid
    $$;


--
-- Name: validate_application_idempotency_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_application_idempotency_actor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM users
     WHERE id = NEW.actor_id AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'application operation actor must belong to the organization';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_country_tax_pack_installation_actor(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_country_tax_pack_installation_actor() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.installed_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users WHERE id = NEW.installed_by AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'country tax pack installer must belong to the installation organization';
  END IF;
  IF NEW.superseded_by IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM users WHERE id = NEW.superseded_by AND org_id = NEW.org_id
  ) THEN
    RAISE EXCEPTION 'country tax pack superseding actor must belong to the installation organization';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_document_posted_period_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_document_posted_period_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_status text;
  current_entry_id uuid;
  current_period_id uuid;
  current_org_id uuid;
  entry_period_id uuid;
  entry_org_id uuid;
BEGIN
  SELECT status, posted_entry_id, posting_period_id, org_id
    INTO current_status, current_entry_id, current_period_id, current_org_id
    FROM documents
   WHERE id = NEW.id;

  -- The document may have been deleted later in the same transaction.
  IF NOT FOUND OR current_status <> 'posted' THEN
    RETURN NULL;
  END IF;
  IF current_entry_id IS NULL OR current_period_id IS NULL THEN
    RAISE EXCEPTION 'posted document requires exact journal and accounting-period identity';
  END IF;
  SELECT period_id, org_id
    INTO entry_period_id, entry_org_id
    FROM journal_entries
   WHERE id = current_entry_id;
  IF entry_period_id IS NULL
     OR entry_org_id <> current_org_id
     OR entry_period_id <> current_period_id THEN
    RAISE EXCEPTION 'document posting period must equal its posted journal period';
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: validate_extra_dims(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_extra_dims(p_org_id uuid, p_dims jsonb, p_subsidiary_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
declare d record;
begin
  if jsonb_typeof(coalesce(p_dims, '{}'::jsonb)) <> 'object' then
    raise exception 'custom segment assignments must be an object' using errcode = '23514';
  end if;
  for d in
    select pair.key, pair.value, sv.subsidiary_id, sv.subsidiary_include_children
      from jsonb_each_text(coalesce(p_dims, '{}'::jsonb)) pair
      left join segment_definitions sd on sd.org_id = p_org_id and sd.key = pair.key
       and sd.source_kind = 'custom' and sd.is_active
      left join segment_values sv on sv.segment_id = sd.id and sv.org_id = sd.org_id
       and sv.id::text = pair.value and sv.is_active
  loop
    if d.subsidiary_include_children is null then
      raise exception 'invalid custom segment assignment for %', d.key using errcode = '23514';
    end if;
    if d.subsidiary_id is not null and p_subsidiary_id is not null and not (
      p_subsidiary_id = d.subsidiary_id or (
        d.subsidiary_include_children and exists (
          with recursive descendants as (
            select id from subsidiaries where id = d.subsidiary_id and org_id = p_org_id
            union all
            select s.id from subsidiaries s join descendants x on s.parent_id = x.id
             where s.org_id = p_org_id
          ) select 1 from descendants where id = p_subsidiary_id
        )
      )
    ) then
      raise exception 'custom segment value % is restricted to another subsidiary', d.value using errcode = '23514';
    end if;
  end loop;
end $$;


--
-- Name: wip_prebill_event_append_only_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wip_prebill_event_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('app.sandbox_wipe',true)='on' THEN RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END; END IF;
  RAISE EXCEPTION 'WIP prebill events are append-only';
END $$;


--
-- Name: wip_prebill_source_reservation_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wip_prebill_source_reservation_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_status text; source_key uuid;
BEGIN
  SELECT status INTO parent_status FROM wip_prebills WHERE org_id=NEW.org_id AND id=NEW.prebill_id;
  IF parent_status NOT IN ('draft','review','approved') THEN RETURN NEW; END IF;
  source_key := coalesce(NEW.time_entry_id, NEW.document_line_id);
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.org_id::text||':'||NEW.source_type||':'||source_key::text,0));
  IF EXISTS (SELECT 1 FROM wip_prebill_lines line JOIN wip_prebills worksheet ON worksheet.org_id=line.org_id AND worksheet.id=line.prebill_id
    WHERE line.org_id=NEW.org_id AND line.id<>NEW.id AND line.source_type=NEW.source_type
      AND coalesce(line.time_entry_id,line.document_line_id)=source_key AND worksheet.status IN ('draft','review','approved'))
  THEN RAISE EXCEPTION 'WIP source is already reserved by an active prebill'; END IF;
  RETURN NEW;
END $$;


