CREATE TABLE public.applications (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    from_line_id uuid NOT NULL,
    to_line_id uuid NOT NULL,
    amount numeric(19,4) NOT NULL,
    applied_on date NOT NULL,
    fx_gain_loss_entry_id uuid,
    unapplied_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    source_amount numeric(19,4) NOT NULL,
    source_transaction_amount numeric(19,4) NOT NULL,
    source_transaction_currency text NOT NULL,
    target_transaction_amount numeric(19,4) NOT NULL,
    target_transaction_currency text NOT NULL,
    settlement_rate numeric(19,10) NOT NULL,
    settlement_rate_source text NOT NULL,
    settlement_rate_reference text NOT NULL,
    settlement_fx_rate_id uuid,
    CONSTRAINT app_positive CHECK ((amount > (0)::numeric)),
    CONSTRAINT app_rate_reference_required CHECK ((length(btrim(settlement_rate_reference)) > 0)),
    CONSTRAINT app_rate_source_valid CHECK ((settlement_rate_source = ANY (ARRAY['same_currency'::text, 'provider'::text, 'manual'::text, 'contractual'::text, 'imported'::text]))),
    CONSTRAINT app_settlement_rate_positive CHECK ((settlement_rate > (0)::numeric)),
    CONSTRAINT app_source_positive CHECK ((source_amount > (0)::numeric)),
    CONSTRAINT app_source_transaction_positive CHECK ((source_transaction_amount > (0)::numeric)),
    CONSTRAINT app_target_transaction_positive CHECK ((target_transaction_amount > (0)::numeric))
);

