    occurred_on date NOT NULL,
    amount numeric(19,4),
    journal_entry_id uuid,
    memo text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    reverses_event_id uuid,
    reversal_reason text,
    CONSTRAINT asset_events_reversal_shape CHECK ((((kind = 'reversed'::text) AND (reverses_event_id IS NOT NULL) AND (journal_entry_id IS NOT NULL) AND (reversal_reason IS NOT NULL) AND ((length(btrim(reversal_reason)) >= 8) AND (length(btrim(reversal_reason)) <= 500))) OR ((kind <> 'reversed'::text) AND (reverses_event_id IS NULL) AND (reversal_reason IS NULL))))
);

