    CONSTRAINT billing_requests_backup_type_check CHECK ((backup_type = ANY (ARRAY['none'::text, 'costed_timesheets'::text, 'quote_only'::text, 'timesheets_purchases'::text, 'purchases'::text, 'purchases_shop_time'::text]))),
