CREATE TABLE public.compliance_records (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    party_id uuid NOT NULL,
    requirement_id uuid NOT NULL,
    project_id uuid,
    status text DEFAULT 'pending_review'::text NOT NULL,
    issuer_name text,
    policy_number text,
    effective_from date NOT NULL,
    expires_on date,
    coverage_amount numeric(19,4),
    aggregate_amount numeric(19,4),
    coverage_currency text,
    additional_insured boolean DEFAULT false NOT NULL,
    waiver_of_subrogation boolean DEFAULT false NOT NULL,
    primary_noncontributory boolean DEFAULT false NOT NULL,
    verified_at timestamp with time zone,
    verified_by uuid,
    rejected_reason text,
    superseded_by_id uuid,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT compliance_records_aggregate CHECK (((aggregate_amount IS NULL) OR (aggregate_amount >= (0)::numeric))),
    CONSTRAINT compliance_records_coverage CHECK (((coverage_amount IS NULL) OR (coverage_amount >= (0)::numeric))),
    CONSTRAINT compliance_records_rejected_reason CHECK (((status = 'rejected'::text) = (rejected_reason IS NOT NULL))),
    CONSTRAINT compliance_records_status CHECK ((status = ANY (ARRAY['pending_review'::text, 'active'::text, 'rejected'::text, 'superseded'::text]))),
    CONSTRAINT compliance_records_verification CHECK (((verified_at IS NULL) = (verified_by IS NULL))),
    CONSTRAINT compliance_records_window CHECK (((expires_on IS NULL) OR (expires_on >= effective_from)))
);

ALTER TABLE ONLY public.compliance_records FORCE ROW LEVEL SECURITY;


--
-- Name: compliance_records; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.compliance_records WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    party_id,
    requirement_id,
    project_id,
    status,
    issuer_name,
    policy_number,
    effective_from,
    expires_on,
    coverage_amount,
    aggregate_amount,
    coverage_currency,
    additional_insured,
    waiver_of_subrogation,
    primary_noncontributory,
    verified_at,
    verified_by,
    rejected_reason,
    superseded_by_id,
    notes,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.compliance_records
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: compliance_release_checks; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.compliance_release_checks (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    party_id uuid NOT NULL,
    document_id uuid,
    payment_run_id uuid,
    payment_instruction_id uuid,
    stage text NOT NULL,
    decision text NOT NULL,
    snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    override_reason text,
    overridden_by uuid,
    checked_at timestamp with time zone DEFAULT now() NOT NULL,
    checked_by uuid,
    CONSTRAINT compliance_release_checks_decision CHECK ((decision = ANY (ARRAY['cleared'::text, 'warned'::text, 'blocked'::text, 'overridden'::text]))),
    CONSTRAINT compliance_release_checks_override CHECK (((decision = 'overridden'::text) = ((override_reason IS NOT NULL) AND (overridden_by IS NOT NULL)))),
    CONSTRAINT compliance_release_checks_stage CHECK ((stage = ANY (ARRAY['run_created'::text, 'readiness'::text, 'run_posted'::text, 'manual'::text])))
);

ALTER TABLE ONLY public.compliance_release_checks FORCE ROW LEVEL SECURITY;


--
-- Name: compliance_release_checks; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.compliance_release_checks WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    party_id,
    document_id,
    payment_run_id,
    payment_instruction_id,
    stage,
    decision,
    snapshot,
    override_reason,
    overridden_by,
    checked_at,
    checked_by
   FROM public.compliance_release_checks
  WHERE (org_id = public.openbooks_query_org_id());


--
-- Name: compliance_requirements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.compliance_requirements (
    id uuid DEFAULT public.uuid_generate_v7() NOT NULL,
    org_id uuid NOT NULL,
    code text NOT NULL,
    name text NOT NULL,
    category text DEFAULT 'insurance'::text NOT NULL,
    class_id uuid,
    requires_expiry boolean DEFAULT true NOT NULL,
    min_coverage_amount numeric(19,4),
    min_aggregate_amount numeric(19,4),
    coverage_currency text,
    requires_additional_insured boolean DEFAULT false NOT NULL,
    requires_waiver_of_subrogation boolean DEFAULT false NOT NULL,
    requires_primary_noncontributory boolean DEFAULT false NOT NULL,
    enforcement text DEFAULT 'warn'::text NOT NULL,
    grace_days integer DEFAULT 0 NOT NULL,
    expiry_warning_days integer DEFAULT 30 NOT NULL,
    requires_verification boolean DEFAULT true NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT compliance_requirements_category CHECK ((category = ANY (ARRAY['insurance'::text, 'tax_form'::text, 'licence'::text, 'bond'::text, 'safety'::text, 'other'::text]))),
    CONSTRAINT compliance_requirements_coverage_currency CHECK ((((min_coverage_amount IS NULL) AND (min_aggregate_amount IS NULL)) OR (coverage_currency IS NOT NULL))),
    CONSTRAINT compliance_requirements_enforcement CHECK ((enforcement = ANY (ARRAY['advisory'::text, 'warn'::text, 'block_payment'::text, 'block_bill'::text]))),
    CONSTRAINT compliance_requirements_grace CHECK (((grace_days >= 0) AND (grace_days <= 365))),
    CONSTRAINT compliance_requirements_min_aggregate CHECK (((min_aggregate_amount IS NULL) OR (min_aggregate_amount > (0)::numeric))),
    CONSTRAINT compliance_requirements_min_coverage CHECK (((min_coverage_amount IS NULL) OR (min_coverage_amount > (0)::numeric))),
    CONSTRAINT compliance_requirements_warning CHECK (((expiry_warning_days >= 0) AND (expiry_warning_days <= 365)))
);

ALTER TABLE ONLY public.compliance_requirements FORCE ROW LEVEL SECURITY;


--
-- Name: compliance_requirements; Type: VIEW; Schema: openbooks_query; Owner: -
--

CREATE VIEW openbooks_query.compliance_requirements WITH (security_barrier='true') AS
 SELECT id,
    org_id,
    code,
    name,
    category,
    class_id,
    requires_expiry,
    min_coverage_amount,
    min_aggregate_amount,
    coverage_currency,
    requires_additional_insured,
    requires_waiver_of_subrogation,
    requires_primary_noncontributory,
    enforcement,
    grace_days,
    expiry_warning_days,
    requires_verification,
    is_active,
    created_at,
    created_by,
    updated_at,
    updated_by
   FROM public.compliance_requirements
  WHERE (org_id = public.openbooks_query_org_id());


