    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    CONSTRAINT lien_waivers_amount CHECK ((amount >= (0)::numeric)),
    CONSTRAINT lien_waivers_direction CHECK ((direction = ANY (ARRAY['received'::text, 'issued'::text]))),
    CONSTRAINT lien_waivers_rejected_reason CHECK (((status = 'rejected'::text) = (rejected_reason IS NOT NULL))),
    CONSTRAINT lien_waivers_signature CHECK (((status <> 'signed'::text) OR ((signed_at IS NOT NULL) AND (length(btrim(COALESCE(signed_by_name, ''::text))) > 0)))),
    CONSTRAINT lien_waivers_status CHECK ((status = ANY (ARRAY['draft'::text, 'requested'::text, 'received'::text, 'signed'::text, 'rejected'::text, 'void'::text]))),
    CONSTRAINT lien_waivers_type CHECK ((waiver_type = ANY (ARRAY['conditional_progress'::text, 'unconditional_progress'::text, 'conditional_final'::text, 'unconditional_final'::text]))),
    CONSTRAINT lien_waivers_void_reason CHECK (((status = 'void'::text) = (void_reason IS NOT NULL)))
);

