    CONSTRAINT vendor_roles_tin_last4 CHECK (((tin_last4 IS NULL) OR (tin_last4 ~ '^[0-9]{4}$'::text))),
    CONSTRAINT vendor_roles_tin_type CHECK (((tin_type IS NULL) OR (tin_type = ANY (ARRAY['ssn'::text, 'ein'::text, 'itin'::text, 'atin'::text, 'sin'::text, 'bn'::text, 'unknown'::text]))))
);

