    CONSTRAINT wip_prebill_lines_adjustment_support_chk CHECK (((adjustment_amount = (0)::numeric) OR ((NULLIF(btrim(adjustment_reason), ''::text) IS NOT NULL) AND (jsonb_array_length(adjustment_evidence) > 0)))),
    CONSTRAINT wip_prebill_lines_amounts_chk CHECK (((quantity > (0)::numeric) AND (cost_amount >= (0)::numeric) AND (original_bill_amount >= (0)::numeric) AND (proposed_bill_amount >= (0)::numeric) AND (adjustment_amount = (proposed_bill_amount - original_bill_amount)))),
    CONSTRAINT wip_prebill_lines_disposition_chk CHECK ((disposition = ANY (ARRAY['bill'::text, 'hold'::text]))),
    CONSTRAINT wip_prebill_lines_evidence_array_chk CHECK ((jsonb_typeof(adjustment_evidence) = 'array'::text)),
    CONSTRAINT wip_prebill_lines_source_shape_chk CHECK ((((source_type = 'time_entry'::text) AND (time_entry_id IS NOT NULL) AND (document_line_id IS NULL)) OR ((source_type = 'document_line'::text) AND (document_line_id IS NOT NULL) AND (time_entry_id IS NULL)))),
    CONSTRAINT wip_prebill_lines_source_type_chk CHECK ((source_type = ANY (ARRAY['time_entry'::text, 'document_line'::text])))
);

