-- Name: psp_settlement_batches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.psp_settlement_batches (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    org_id uuid NOT NULL,
    provider text NOT NULL,
    external_ref text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    currency text NOT NULL,
    gross_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fee_amount numeric(19,4) DEFAULT 0 NOT NULL,
    refund_amount numeric(19,4) DEFAULT 0 NOT NULL,
    dispute_amount numeric(19,4) DEFAULT 0 NOT NULL,
    net_amount numeric(19,4) DEFAULT 0 NOT NULL,
    fx_amount numeric(19,4) DEFAULT 0 NOT NULL,
    settlement_date date NOT NULL,
    bank_account_id uuid,
    fee_account_id uuid,
    dispute_account_id uuid,
    fx_account_id uuid,
    clearing_account_id uuid,
    subsidiary_id uuid,
    journal_entry_id uuid,
    source_payload jsonb,
    line_count integer DEFAULT 0 NOT NULL,
    posted_at timestamp with time zone,
    memo text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    reversal_entry_id uuid,
    reversal_reason text,
    reversed_at timestamp with time zone,
    reversed_by uuid,
    CONSTRAINT psp_settlement_batches_lifecycle_evidence CHECK ((((status = 'draft'::text) AND (journal_entry_id IS NULL) AND (posted_at IS NULL) AND (reversal_entry_id IS NULL) AND (reversal_reason IS NULL) AND (reversed_at IS NULL) AND (reversed_by IS NULL)) OR ((status = 'posted'::text) AND (journal_entry_id IS NOT NULL) AND (posted_at IS NOT NULL) AND (reversal_entry_id IS NULL) AND (reversal_reason IS NULL) AND (reversed_at IS NULL) AND (reversed_by IS NULL)) OR ((status = 'void'::text) AND (journal_entry_id IS NOT NULL) AND (posted_at IS NOT NULL) AND (reversal_entry_id IS NOT NULL) AND (reversal_entry_id <> journal_entry_id) AND (reversal_reason IS NOT NULL) AND ((length(btrim(reversal_reason)) >= 5) AND (length(btrim(reversal_reason)) <= 500)) AND (reversed_at IS NOT NULL) AND (reversed_by IS NOT NULL)))),
    CONSTRAINT psp_settlement_batches_provider_chk CHECK ((provider = ANY (ARRAY['stripe'::text, 'adyen'::text, 'gocardless'::text, 'recurly'::text, 'chargebee'::text]))),
    CONSTRAINT psp_settlement_batches_status_chk CHECK ((status = ANY (ARRAY['draft'::text, 'posted'::text, 'void'::text])))
);

