-- Name: jl_entry; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX jl_entry ON public.journal_lines USING btree (entry_id);


--
-- Name: jl_org_account; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX jl_org_account ON public.journal_lines USING btree (org_id, account_id);


--
-- Name: jl_org_account_covering; Type: INDEX; Schema: public; Owner: -
--
-- GL aggregation (trial balance, statements, account balances) reads
-- (entry_id, amount, subsidiary_id) per (org, account) as an index-only scan;
-- the trailing columns are payload, not seek keys. Under row-level security a
-- numeric key column could never be a seek condition anyway: numeric_eq is
-- not LEAKPROOF, so the planner will not push amount predicates into any
-- index condition on tenant-scoped queries.
--

CREATE INDEX jl_org_account_covering ON public.journal_lines USING btree (org_id, account_id, entry_id, amount, subsidiary_id);


--
-- Name: jl_org_foreign_currency; Type: INDEX; Schema: public; Owner: -
--
-- The multi-currency feature default asks "has this org ever posted a foreign
-- currency line?" on every request. Partial: empty on a single-currency
-- tenant, so the negative answer costs one index probe instead of a scan of
-- every journal line.
--

CREATE INDEX jl_org_foreign_currency ON public.journal_lines USING btree (org_id) WHERE (fx_rate <> (1)::numeric);


--
-- Name: jl_org_account_posting_date; Type: INDEX; Schema: public; Owner: -
--

CREATE INDEX jl_org_account_posting_date ON public.journal_lines USING btree (org_id, account_id, posting_date);


--
-- Name: jl_org_posting_date; Type: INDEX; Schema: public; Owner: -
--
-- Date-ranged GL reads answered from the line alone, without joining the entry.
--

CREATE INDEX jl_org_posting_date ON public.journal_lines USING btree (org_id, posting_date);


