--

CREATE POLICY tax_group_members_org_isolation ON public.tax_group_members USING (((current_setting('app.bypass_rls'::text, true) = 'on'::text) OR (EXISTS ( SELECT 1
   FROM public.tax_groups tg
  WHERE ((tg.id = tax_group_members.tax_group_id) AND ((tg.org_id)::text = current_setting('app.current_org'::text, true))))))) WITH CHECK (((current_setting('app.bypass_rls'::text, true) = 'on'::text) OR (EXISTS ( SELECT 1
   FROM public.tax_groups tg
  WHERE ((tg.id = tax_group_members.tax_group_id) AND ((tg.org_id)::text = current_setting('app.current_org'::text, true)))))));


